@layer reset, base, components, pages, responsive, polish, overhaul, guangguang;

@layer reset {
  *, *::before, *::after { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body { margin: 0; min-width: 320px; min-height: 100vh; }
  button, input { font: inherit; }
  button, a { -webkit-tap-highlight-color: transparent; }
  button { border: 0; }
  a { color: inherit; text-decoration: none; }
  h1, h2, h3, p, dl, dd { margin: 0; }
}

/* Student dashboard focus pass: fewer simultaneous choices, progressive disclosure. */
@layer overhaul {
  .discovery-home-focused .explore-header nav { gap: clamp(16px,2.2vw,30px); }
  .discovery-home-focused .explore-header nav a { color: #617579; font-size: 12px; font-weight: 760; }
  .discovery-home-focused .discovery-field-section { padding-block: clamp(38px,4vw,58px); scroll-margin-top: 96px; }
  .discovery-home-focused .discovery-section-title { grid-template-columns: minmax(0,1fr) minmax(230px,.55fr); padding-bottom: 20px; }
  .discovery-home-focused .discovery-section-title h2 { font-size: clamp(27px,3vw,40px); }
  .discovery-home-focused .discovery-field-grid { grid-template-columns: repeat(3,minmax(0,1fr)); gap: 12px; margin-top: 20px; border: 0; }
  .discovery-home-focused .discovery-field-card-compact {
    min-height: 218px;
    padding: 20px 21px;
    border: 1px solid #c9c2b6;
    background: #fbf8f0;
    box-shadow: 0 7px 22px rgba(30,57,61,.035);
  }
  .discovery-home-focused .discovery-field-card-compact:hover { transform: translateY(-3px); box-shadow: 0 12px 28px rgba(31,66,73,.09); }
  .discovery-home-focused .discovery-field-card-compact .discovery-card-top { width: 100%; }
  .discovery-home-focused .discovery-field-card-compact .discovery-field-title { margin-top: 22px; }
  .discovery-home-focused .discovery-field-card-compact .discovery-field-title > i { width: 38px; height: 38px; }
  .discovery-home-focused .discovery-field-card-compact .discovery-field-title h2 { font-size: 21px; }
  .discovery-home-focused .discovery-field-card-compact > p { margin-top: 8px; color: #6e7d7e; font-size: 12px; line-height: 1.55; }
  .discovery-home-focused .discovery-field-card-compact .discovery-field-enter { padding-top: 11px; font-size: 11px; }

  .discovery-home-focused .dashboard-cat-guide {
    min-height: 0;
    grid-template-columns: 92px minmax(240px,.82fr) minmax(360px,1.18fr);
    gap: clamp(18px,2.4vw,30px);
    margin-top: 18px;
    padding: 21px 23px;
    border-color: #cabda7;
    background: linear-gradient(100deg,rgba(235,154,66,.12),transparent 24%),#fffaf0;
    box-shadow: 0 12px 34px rgba(82,61,38,.07);
  }
  .discovery-home-focused .dashboard-cat-portrait { min-height: 96px; }
  .discovery-home-focused .dashboard-cat-portrait .orange-cat-avatar { width: 100px; height: 96px; }
  .discovery-home-focused .dashboard-cat-copy > span { font-size: 8px; }
  .discovery-home-focused .dashboard-cat-copy h3 { margin-top: 5px; font-size: clamp(18px,1.8vw,23px); }
  .discovery-home-focused .dashboard-cat-copy p { margin-top: 6px; font-size: 11px; line-height: 1.6; }
  .discovery-home-focused .dashboard-cat-copy > a { margin-top: 9px; }
  .discovery-home-focused .dashboard-cat-guide form { padding: 15px; box-shadow: 4px 4px 0 #e5a45a; }
  .discovery-home-focused .dashboard-cat-guide form > label { font-size: 11px; }
  .discovery-home-focused .dashboard-cat-guide form > div { margin-top: 8px; }
  .discovery-home-focused .dashboard-cat-guide input { min-height: 43px; }
  .discovery-home-focused .dashboard-cat-guide form > small { margin-top: 7px; }
  .discovery-home-focused .dashboard-knowledge-result {
    grid-column: 1/-1;
    grid-template-columns: auto minmax(0,1fr);
    gap: 12px 16px;
    padding: 14px;
    border-top-width: 2px;
    background: #f3ecdd;
  }
  .discovery-home-focused .dashboard-knowledge-result > header > svg { width: 32px; height: 32px; padding: 7px; }
  .discovery-home-focused .dashboard-knowledge-result > header strong { font-size: 12px; }
  .discovery-home-focused .dashboard-knowledge-result > details { min-width: 0; align-self: center; }
  .discovery-home-focused .dashboard-knowledge-result > details > summary {
    min-height: 38px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 8px 11px;
    color: #31545a;
    border: 1px solid #b7aa94;
    background: rgba(255,255,255,.46);
    cursor: pointer;
    font-size: 11px;
    font-weight: 800;
    list-style: none;
  }
  .discovery-home-focused .dashboard-knowledge-result > details > summary::-webkit-details-marker { display: none; }
  .discovery-home-focused .dashboard-knowledge-result > details[open] > summary svg { transform: rotate(90deg); }
  .discovery-home-focused .knowledge-result-details { display: grid; gap: 12px; padding-top: 14px; }

  .discovery-more {
    width: calc(100% - 2 * var(--page-gutter));
    max-width: calc(var(--site-width) - 2 * var(--page-gutter));
    margin: 26px auto 72px;
    scroll-margin-top: 92px;
    border: 1px solid #c7c0b4;
    background: #ebe6dc;
  }
  .discovery-more > summary {
    min-height: 88px;
    display: grid;
    grid-template-columns: minmax(260px,.9fr) minmax(300px,1.1fr) auto;
    align-items: center;
    gap: 28px;
    padding: 20px 24px;
    color: #23444c;
    cursor: pointer;
    list-style: none;
  }
  .discovery-more > summary::-webkit-details-marker { display: none; }
  .discovery-more > summary span { display: grid; gap: 4px; }
  .discovery-more > summary small { color: #b06b32; font: 800 8px var(--mono); letter-spacing: .1em; }
  .discovery-more > summary strong { font: 700 20px var(--serif); }
  .discovery-more > summary p { color: #708084; font-size: 12px; }
  .discovery-more > summary > svg { transition: transform .2s ease; }
  .discovery-more[open] > summary { border-bottom: 1px solid #c7c0b4; background: #f4efe5; }
  .discovery-more[open] > summary > svg { transform: rotate(90deg); }
  .discovery-resource-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 10px; padding: 18px; }
  .discovery-resource-grid > a { min-width: 0; min-height: 76px; display: grid; grid-template-columns: 34px minmax(0,1fr) auto; align-items: center; gap: 10px; padding: 13px; color: #31535b; border: 1px solid #c8c0b1; background: #faf7ef; }
  .discovery-resource-grid > a:hover { color: #9c562c; border-color: #d29a64; background: #fffaf0; }
  .discovery-resource-grid > a > span { min-width: 0; display: grid; gap: 3px; }
  .discovery-resource-grid small { color: #9a683d; font-size: 9px; font-weight: 800; }
  .discovery-resource-grid strong { overflow: hidden; font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
  .discovery-question-section-compact { grid-template-columns: minmax(220px,.48fr) minmax(0,1.52fr); gap: 24px; margin: 0; padding: 28px; }
  .discovery-question-section-compact .discovery-question-heading { position: static; }
  .discovery-question-section-compact .discovery-question-heading h2 { font-size: 27px; }
  .discovery-question-section-compact .knowledge-graph-stats { display: none; }
  .discovery-question-section-compact .discovery-question-list { max-height: 350px; overflow: auto; }

  .discovery-home-focused .page-intro-trigger { width: 42px; min-width: 42px; height: 42px; padding: 0; border-radius: 50%; }
  .discovery-home-focused .page-intro-trigger span { display: none; }
}

@layer guangguang {
  @media (max-width: 1050px) {
    .discovery-home-focused .dashboard-cat-guide { grid-template-columns: 82px minmax(0,1fr); }
    .discovery-home-focused .dashboard-cat-guide form { grid-column: 1/-1; }
    .discovery-home-focused .discovery-field-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
    .discovery-question-section-compact { grid-template-columns: 1fr; }
  }
  @media (max-width: 700px) {
    .discovery-home-focused { padding-bottom: 76px; }
    .discovery-home-focused .page-intro-trigger { right: 12px; bottom: 84px; }
    .discovery-home-focused .student-mobile-dock { grid-template-columns: repeat(4,1fr); }
    .discovery-home-focused .discovery-field-section { margin-inline: 12px; padding-block: 28px; scroll-margin-top: 82px; }
    .discovery-home-focused .discovery-section-title { grid-template-columns: 1fr; gap: 8px; }
    .discovery-home-focused .discovery-section-title h2 { font-size: 29px; line-height: 1.38; }
    .discovery-home-focused .discovery-section-title p { justify-self: start; }
    .discovery-home-focused .discovery-field-grid { grid-template-columns: 1fr; gap: 9px; }
    .discovery-home-focused .discovery-field-card-compact { min-height: 148px; padding: 15px 17px; }
    .discovery-home-focused .discovery-field-card-compact .discovery-field-title { margin-top: 10px; }
    .discovery-home-focused .discovery-field-card-compact .discovery-field-title h2 { font-size: 19px; }
    .discovery-home-focused .discovery-field-card-compact > p { margin-top: 5px; }
    .discovery-home-focused .discovery-field-card-compact .discovery-field-enter { padding-top: 8px; }
    .discovery-home-focused .dashboard-cat-guide { grid-template-columns: 66px minmax(0,1fr); margin-top: 10px; padding: 16px; }
    .discovery-home-focused .dashboard-cat-portrait { min-height: 74px; }
    .discovery-home-focused .dashboard-cat-portrait .orange-cat-avatar { width: 74px; height: 72px; }
    .discovery-home-focused .dashboard-cat-copy > span,.discovery-home-focused .dashboard-cat-copy p { display: none; }
    .discovery-home-focused .dashboard-cat-copy h3 { font-size: 18px; }
    .discovery-home-focused .dashboard-knowledge-result { grid-template-columns: 1fr; }
    .discovery-more { width: calc(100% - 24px); margin-block: 20px 32px; }
    .discovery-more > summary { min-height: 78px; grid-template-columns: minmax(0,1fr) auto; gap: 12px; padding: 16px; }
    .discovery-more > summary p { display: none; }
    .discovery-more > summary strong { font-size: 17px; }
    .discovery-resource-grid { grid-template-columns: 1fr; padding: 12px; }
    .discovery-question-section-compact { padding: 24px 14px; }
    .discovery-question-section-compact .discovery-question-list { max-height: 420px; }
  }
}

/* Guangguang panel: calm, progressive-disclosure layout. */
@layer guangguang {
  .harness-panel.cat-partner-panel {
    width: min(424px,calc(100vw - 32px));
    grid-template-rows: auto auto minmax(0,1fr) auto;
    border: 1px solid #7b4b2b;
    border-radius: 18px;
    background: #fbf7ee;
    box-shadow: 0 24px 70px rgba(31,25,19,.3),0 0 0 1px rgba(255,255,255,.7);
  }
  .cat-partner-panel > header {
    min-height: 58px;
    grid-template-columns: 42px minmax(0,1fr) auto;
    gap: 10px;
    padding: 6px 10px 6px 7px;
    border-bottom: 0;
    background: radial-gradient(circle at 10% 0,rgba(241,157,70,.2),transparent 34%),#20383e;
  }
  .cat-partner-panel .cat-panel-mark,.cat-panel-mark .orange-cat-avatar { width: 41px; height: 41px; }
  .cat-partner-panel > header strong { font-size: 18px !important; letter-spacing: .04em; }
  .cat-partner-panel > header > div:nth-child(2) { gap: 0; }
  .cat-partner-panel > header > div:nth-child(2) > span { font-size: 8px !important; letter-spacing: .1em; }
  .cat-partner-panel > header > div:nth-child(2) > small { color: #aec0bc; font-size: 9px !important; }
  .cat-panel-actions > button:last-child { border-radius: 9px; }

  .cat-panel-tabs {
    min-height: 43px;
    padding: 4px;
    gap: 5px;
    border-bottom: 1px solid #d7cbb8;
    background: #eee6d8;
  }
  .cat-panel-tabs button {
    min-height: 35px;
    gap: 6px;
    padding: 5px 8px;
    border: 0;
    border-radius: 10px;
    font-size: 12px;
    font-weight: 800;
  }
  .cat-panel-tabs button > span { display: block; text-align: center; font-size: 11px !important; }
  .cat-panel-tabs button.active { color: #213e44; background: #fffaf0; box-shadow: 0 2px 8px rgba(70,48,31,.09),inset 0 -2px #e88838; }

  .cat-partner-panel .harness-dialogue-body { background: #fbf7ee; }
  .cat-partner-panel .panel-view-dialogue { display: flex; flex-direction: column; overflow: hidden; }
  .cat-partner-panel .harness-dialogue-context {
    min-height: 38px;
    flex: 0 0 auto;
    order: 0;
    gap: 12px;
    padding: 6px 11px;
    color: #edf7f4;
    border-bottom: 0;
    background: #2a464a;
  }
  .cat-partner-panel .harness-dialogue-context > div:first-child { display: flex; align-items: center; gap: 8px; }
  .cat-partner-panel .harness-dialogue-context > div:first-child span { color: #dca56b; font-size: 9px; }
  .cat-partner-panel .harness-dialogue-context > div:first-child strong { font-size: 13px; }
  .cat-partner-panel .harness-dialogue-metrics { display: flex; gap: 9px; }
  .cat-partner-panel .harness-dialogue-metrics span { font-size: 9px; }

  .cat-partner-panel .harness-smart-coach {
    min-height: 62px;
    grid-template-columns: 20px minmax(0,1fr) auto 32px;
    align-items: center;
    flex: 0 0 auto;
    order: 1;
    gap: 8px;
    margin: 8px 10px 0;
    padding: 9px 10px;
    border-radius: 12px;
    border-left-width: 3px;
    box-shadow: none;
  }
  .cat-partner-panel .harness-smart-coach::after { display: none; }
  .cat-partner-panel .harness-smart-coach-mark { color: var(--coach-color); }
  .cat-partner-panel .harness-smart-coach-copy { min-width: 0; display: grid; gap: 2px; }
  .cat-partner-panel .harness-smart-coach-copy small { color: var(--coach-color); font-size: 8px; font-weight: 900; letter-spacing: .05em; }
  .cat-partner-panel .harness-smart-coach-copy strong { display: -webkit-box; overflow: hidden; color: #435d61; font-size: 11px; line-height: 1.45; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
  .cat-partner-panel .harness-smart-coach-action { min-height: 33px; display: inline-flex; align-items: center; gap: 5px; padding: 0 9px; color: white; border: 1px solid var(--coach-color); border-radius: 8px; background: var(--coach-color); cursor: pointer; font-size: 9px; font-weight: 900; }
  .cat-partner-panel .harness-smart-coach-action span { max-width: 86px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .cat-partner-panel .harness-smart-coach-locate { width: 32px; min-height: 33px; display: grid; place-items: center; padding: 0; color: var(--coach-color); border: 1px solid color-mix(in srgb,var(--coach-color) 55%,white); border-radius: 8px; background: white; cursor: pointer; }
  .cat-partner-panel .harness-smart-coach-action:hover,.cat-partner-panel .harness-smart-coach-locate:hover { color: #173847; border-color: #173847; background: #72e0ca; }

  .harness-support-tools {
    flex: 0 0 auto;
    order: 3;
    margin: 0 10px 9px;
    overflow: hidden;
    border: 1px solid #d1c5b2;
    border-radius: 12px;
    background: rgba(255,253,247,.72);
  }
  .harness-support-tools > summary {
    min-height: 39px;
    display: grid;
    grid-template-columns: 22px minmax(0,1fr) auto 16px;
    align-items: center;
    gap: 7px;
    padding: 6px 9px;
    color: #345459;
    cursor: pointer;
    list-style: none;
  }
  .harness-support-tools > summary::-webkit-details-marker { display: none; }
  .harness-support-tools > summary > svg:first-child { color: #d98233; }
  .harness-support-tools > summary > span { min-width: 0; display: grid; gap: 1px; }
  .harness-support-tools > summary strong { font-size: 11px; }
  .harness-support-tools > summary small { display: none; }
  .harness-support-tools > summary > b { display: none; }
  .harness-support-tools > summary > svg:last-child { color: #8d867a; transition: transform .2s ease; }
  .harness-support-tools[open] > summary { background: #f4ecdd; }
  .harness-support-tools[open] > summary > svg:last-child { transform: rotate(180deg); }
  .harness-support-tools-body { display: grid; gap: 8px; max-height: 330px; padding: 9px; overflow-y: auto; border-top: 1px solid #ddd3c2; background: #f7f0e4; }
  .harness-support-tools-body .harness-learning-branch,
  .harness-support-tools-body .harness-memory-line,
  .harness-support-tools-body .harness-hint-ladder,
  .harness-support-tools-body .harness-question-library { margin: 0; box-shadow: none; }
  .harness-support-tools-body .harness-learning-branch { border-radius: 9px; }
  .harness-support-tools-body .harness-learning-branch p { font-size: 9px; }
  .harness-support-tools-body .harness-memory-line { border-radius: 9px; }
  .harness-support-tools-body .harness-hint-ladder { border-radius: 9px; }
  .harness-support-tools-body .harness-hint-ladder > header { padding: 8px 9px; }
  .harness-support-tools-body .harness-hint-ladder > div button { min-height: 49px; }
  .harness-support-tools-body .harness-question-library { border-radius: 9px; }

  .cat-partner-panel .harness-chat {
    min-height: 0;
    display: grid;
    grid-template-rows: minmax(0,1fr) auto auto;
    flex: 1 1 auto;
    order: 2;
    margin: 8px 10px;
    border: 0;
    border-radius: 13px;
    background: #f1eadf;
    box-shadow: 0 0 0 1px #d1c7b8;
  }
  .cat-partner-panel .harness-chat-stream {
    min-height: 72px;
    max-height: none;
    gap: 9px;
    padding: 11px;
    background: #fffdf8;
  }
  .cat-partner-panel .harness-message { grid-template-columns: 26px minmax(0,1fr); gap: 7px; }
  .cat-partner-panel .harness-message > i { width: 25px; height: 25px; }
  .cat-partner-panel .harness-message > i .orange-cat-avatar { width: 31px; height: 31px; }
  .cat-partner-panel .harness-message > div { padding: 8px 9px; border-radius: 9px; }
  .cat-partner-panel .harness-message small { margin-bottom: 2px; font-size: 8px; }
  .cat-partner-panel .harness-message p { font-size: 12px; line-height: 1.58; }
  .cat-partner-panel .harness-message em { margin-top: 4px; }
  .cat-partner-panel .harness-message.learner { grid-template-columns: minmax(0,1fr) 26px; padding-left: 44px; }
  .cat-partner-panel .harness-message.welcome > div { padding-block: 9px; }
  .cat-partner-panel .harness-message.welcome p { line-height: 1.5; }
  .harness-history-toggle {
    min-height: 29px;
    padding: 4px 10px;
    color: #7b704f;
    border: 1px dashed #cbbb9f;
    border-radius: 15px;
    background: #faf4e8;
    font-size: 9px;
    cursor: pointer;
  }
  .harness-history-toggle:hover { color: #8e4a21; border-color: #dc914d; }
  .cat-partner-panel .harness-quick-questions { padding: 7px 8px; }
  .cat-partner-panel .harness-quick-questions > span { display: none; }
  .cat-partner-panel .harness-quick-questions > div { flex-wrap: nowrap; gap: 5px; margin-top: 0; overflow-x: auto; }
  .cat-partner-panel .harness-quick-questions button { min-height: 27px; max-width: calc(50% - 3px); flex: 1 1 50%; overflow: hidden; border-radius: 14px; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
  .cat-partner-panel .harness-composer { position: sticky; bottom: 0; grid-template-columns: 1fr auto auto; background: #fbf7ef; }
  .cat-partner-panel .harness-composer:not(:has(.harness-save-observation)) .harness-send { grid-column: 1/-1; }
  .cat-partner-panel .harness-composer textarea { min-height: 52px; max-height: 96px; padding: 9px 10px; resize: none; font-size: 12px; line-height: 1.5; }
  .cat-partner-panel .harness-composer > button { min-height: 36px; font-size: 10px; }
  .cat-partner-panel .harness-composer > small { display: none; }

  .panel-view-review .cat-review-intro {
    min-height: 45px;
    grid-template-columns: 27px minmax(0,1fr);
    margin: 9px 11px 0;
    padding: 8px 9px;
    border: 0;
    border-radius: 11px;
    box-shadow: none;
  }
  .panel-view-review .cat-review-intro::after { display: none; }
  .panel-view-review .cat-review-intro > svg { width: 26px; height: 26px; padding: 5px; }
  .panel-view-review .cat-review-intro strong { font-size: 10px !important; }
  .panel-view-review .cat-review-intro p { display: none; }
  .panel-view-review .harness-inquiry-state,
  .panel-view-review .harness-learner-model,
  .panel-view-review .harness-long-memory,
  .panel-view-review .harness-concept-map,
  .panel-view-review .harness-session-summary { margin-right: 11px; margin-left: 11px; border-radius: 11px; box-shadow: none; }
  .panel-view-review .harness-inquiry-state { margin-top: 8px; padding: 10px 11px; }

  .harness-long-memory { display: block; padding: 0; overflow: hidden; }
  .harness-long-memory > summary {
    min-height: 49px;
    display: grid;
    grid-template-columns: minmax(0,1fr) auto 16px;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    cursor: pointer;
    list-style: none;
  }
  .harness-long-memory > summary::-webkit-details-marker { display: none; }
  .harness-long-memory > summary > span { min-width: 0; display: grid; grid-template-columns: 20px auto 1fr; align-items: center; gap: 5px; }
  .harness-long-memory > summary > span svg { color: var(--memory-color); }
  .harness-long-memory > summary small { color: #728b98; font-size: 8px; }
  .harness-long-memory > summary strong { overflow: hidden; color: #173f54; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
  .harness-long-memory > summary > b { color: var(--memory-color); font: 900 15px var(--mono); white-space: nowrap; }
  .harness-long-memory > summary > b small { margin-left: 3px; font-size: 7px; }
  .harness-long-memory > summary > svg { color: #738b95; transition: transform .2s ease; }
  .harness-long-memory[open] > summary > svg { transform: rotate(180deg); }
  .harness-long-memory-body { display: grid; gap: 9px; padding: 10px; border-top: 1px solid #cbdde4; }
  .harness-long-memory-body > p { display: flex; align-items: flex-start; gap: 6px; color: #536f7b; font-size: 9px; line-height: 1.55; }
  .harness-long-memory-body > p svg { flex: 0 0 auto; margin-top: 1px; color: var(--memory-color); }
