    background: rgba(125,229,255,.12);
  }
  .vision-diagnostic-grid article {
    min-height: 112px;
    display: grid;
    align-content: center;
    gap: 6px;
    padding: 15px 17px;
    background: #f0eee7;
  }
  .vision-diagnostic-grid article > span { display: flex; align-items: center; gap: 7px; color: #71848b; font: 800 9px var(--mono); letter-spacing: .06em; }
  .vision-diagnostic-grid article strong { color: #153542; font: 800 18px var(--mono); letter-spacing: -.025em; }
  .vision-diagnostic-grid article small { color: #7c8c90; font-size: 10px; }
  .vision-diagnostic-grid article.warn { box-shadow: inset 0 3px var(--vision-coral); }
  .vision-diagnostic-grid article.warn strong { color: #d16055; }
  .vision-diagnostic-grid article.good { box-shadow: inset 0 3px var(--vision-mint); }
  .vision-diagnostic-grid article.good strong { color: #168675; }

  .vision-clinical-verdict {
    min-height: 118px;
    display: grid;
    grid-template-columns: 48px minmax(0,1fr) auto;
    align-items: center;
    gap: 16px;
    padding: 17px 20px;
    color: #dceef5;
    border: 1px solid rgba(125,229,255,.2);
    border-left: 4px solid var(--vision-cyan);
    background: linear-gradient(105deg,#0d3040,#071e2b 72%);
  }
  .vision-clinical-verdict > i {
    width: 46px;
    height: 46px;
    display: grid;
    place-items: center;
    color: var(--vision-cyan);
    border: 1px solid currentColor;
    border-radius: 50%;
    box-shadow: inset 0 0 17px rgba(125,229,255,.09),0 0 18px rgba(125,229,255,.08);
  }
  .vision-clinical-verdict > div { min-width: 0; display: grid; gap: 4px; }
  .vision-clinical-verdict small { color: #6e94a5; font: 800 8px var(--mono); letter-spacing: .12em; }
  .vision-clinical-verdict strong { color: #edfaff; font-size: 16px; }
  .vision-clinical-verdict p { margin: 0; color: #8eacba; font-size: 11px; line-height: 1.65; }
  .vision-clinical-verdict > span { display: grid; justify-items: end; gap: 4px; }
  .vision-clinical-verdict > span b { padding: 7px 9px; color: var(--vision-cyan); border: 1px solid currentColor; font: 800 9px var(--mono); letter-spacing: .12em; }
  .vision-clinical-verdict > span em { color: #668899; font-size: 9px; font-style: normal; }
  .vision-clinical-verdict.warning { border-left-color: var(--vision-coral); }
  .vision-clinical-verdict.warning > i,
  .vision-clinical-verdict.warning > span b { color: var(--vision-coral); }
  .vision-clinical-verdict.correct { border-color: rgba(94,228,193,.3); border-left-color: var(--vision-mint); background: linear-gradient(105deg,#103a3d,#072328 72%); }
  .vision-clinical-verdict.correct > i,
  .vision-clinical-verdict.correct > span b { color: var(--vision-mint); }

  .vision-correction-experience:fullscreen > .vision-case-selector { display: none; }
  .vision-correction-experience:fullscreen > .vision-mode-bar { flex: 0 0 70px; }
  .vision-correction-experience:fullscreen > :is(.vision-optical-stage,.vision-3d-stage) { flex: 1 1 auto; min-height: 0; }
  .vision-correction-experience:fullscreen > .vision-prescription-console { flex: 0 0 auto; }
  .vision-correction-experience:fullscreen .vision-prescription-console > header,
  .vision-correction-experience:fullscreen > :is(.vision-diagnostic-grid,.vision-clinical-verdict,.lens-module-guide) { display: none; }
  .vision-correction-experience:fullscreen .vision-prescription-console button { min-height: 78px; padding-block: 8px; }
  .vision-correction-experience:fullscreen .vision-lens-glyph { height: 52px; }

  @keyframes vision-ray-flow { to { stroke-dashoffset: -46; } }
  @keyframes vision-focus-spin { to { rotate: 360deg; } }
  @keyframes vision-focus-pulse { 0%,100% { opacity: .45; scale: .7; } 50% { opacity: 1; scale: 1.15; } }
  @keyframes vision-panel-scan { from { left: -25%; } to { left: 115%; } }

  @media (max-width: 980px) {
    .vision-mode-bar { grid-template-columns: 1fr; }
    .vision-mode-bar > span { border-right: 0; border-bottom: 1px solid rgba(125,229,255,.15); }
    .vision-case-selector > div { grid-template-columns: 1fr; }
    .vision-optical-stage { overflow-x: auto; overscroll-behavior-inline: contain; }
    .vision-diagnostic-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  }
  @media (max-width: 720px) {
    .vision-case-selector > header,
    .vision-prescription-console > header { align-items: flex-start; flex-direction: column; gap: 5px; }
    .vision-mode-bar .lens-dimension-switch { flex-direction: column; align-items: stretch; }
    .vision-mode-bar .lens-dimension-switch nav { width: 100%; }
    .vision-mode-bar .lens-dimension-switch button { min-width: 0; }
    .vision-optical-stage { min-height: 404px; }
    .vision-optical-stage > svg { min-width: 760px; }
    .vision-prescription-console > div { grid-template-columns: 1fr; }
    .vision-prescription-console button { min-height: 98px; }
    .vision-focus-console { right: 12px; bottom: 12px; left: 12px; min-width: 0; }
    .vision-clinical-verdict { grid-template-columns: 42px minmax(0,1fr); }
    .vision-clinical-verdict > span { grid-column: 2; grid-row: 2; justify-items: start; }
  }
  @media (max-width: 520px) {
    .vision-case-selector button { min-height: 100px; grid-template-columns: 40px minmax(0,1fr); gap: 11px; padding: 13px; }
    .vision-case-selector button > i { width: 39px; height: 39px; }
    .vision-case-selector button > b { display: none; }
    .vision-mode-bar > span small { white-space: normal; }
    .vision-mode-bar .lens-dimension-switch nav { grid-template-columns: 1fr; }
    .vision-mode-bar .lens-dimension-switch button { border-right: 0; border-bottom: 1px solid rgba(125,229,255,.14); }
    .vision-diagnostic-grid { grid-template-columns: 1fr; }
    .vision-diagnostic-grid article { min-height: 92px; }
    .vision-focus-console { grid-template-columns: auto 1fr; }
    .vision-focus-console > b { grid-column: 2; width: max-content; }
    .vision-clinical-verdict { padding: 15px; }
    .vision-clinical-verdict p { font-size: 10px; }
  }
  @media (prefers-reduced-motion: reduce) {
    .vision-source-rays path,
    .vision-focus-marker circle,
    .vision-focus-marker circle:nth-child(2) { animation: none; }
  }
}

/* Frontend system v4: legible scientific editorial UI across every product surface. */
@layer overhaul {
  :root {
    --font-display: "Songti SC", "STSong", "Noto Serif CJK SC", serif;
    --font-body: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
    --font-data: "SFMono-Regular", "Cascadia Code", "Roboto Mono", monospace;
    --surface-0: #f3f7f8;
    --surface-1: rgba(255,255,255,.82);
    --surface-2: #e8f1f4;
    --ui-line: rgba(24,80,100,.17);
    --ui-line-strong: rgba(52,154,193,.34);
    --ui-blue: #58c8ef;
    --ui-cyan: #75e0f6;
    --ui-teal: #38bca9;
    --ui-radius: 6px;
    --ui-radius-lg: 12px;
    --ui-focus: 0 0 0 3px rgba(88,200,239,.18);
  }

  body { font-family: var(--font-body); font-weight: 400; letter-spacing: 0; }
  body *, body *::before, body *::after { font-family: inherit !important; }
