  body :is(code,kbd,pre,.version-chip,[class*="eyebrow"],small,[class*="number"],[class*="coordinate"],[class*="status"] span) { font-family: var(--font-data) !important; }
  body :is(p,li,span,small,label,input,textarea,select,option,output,dt,dd,th,td,a) { font-weight: 400 !important; }
  body :is(h1,h2,h3,strong,b,button,th) { font-weight: 700 !important; }
  body :is(input,textarea,select,button) { font-family: var(--font-body) !important; }
  body :is(input,textarea,select) { min-height: 42px; font-size: max(13px,1em); }
  body :is(button,a,[role="button"]) { touch-action: manipulation; }
  body :is(button,a,input,textarea,select):focus-visible { outline: 0; box-shadow: var(--ui-focus); }
  ::placeholder { color: #78909a; opacity: .82; }

  .home-nav,.explore-header,.workbench-header { min-height: 72px; backdrop-filter: blur(18px) saturate(1.25); }
