  .home-nav nav a::after,.explore-header nav a::after { position: absolute; right: 50%; bottom: 4px; left: 50%; height: 2px; content: ""; background: currentColor; transition: right .2s ease,left .2s ease; }
  .home-nav nav a:hover::after,.explore-header nav a:hover::after,.explore-header nav a.active::after { right: 3px; left: 3px; }
  .brand-symbol { border-radius: var(--ui-radius); }

  .home-page .hero-lab { min-height: min(820px,calc(100vh - 72px)); }
  .home-page .hero-copy { align-self: center; }
