  .teacher-view > :is(section,article),.teacher-view-toolbar,.teacher-account-console,.teacher-real-class-grid > article,.teacher-flow-library,.teacher-flow-lessons,.teacher-task-board,.teacher-report-sheet { border-radius: var(--tc-radius); }
