/* Student personal flight deck: a light, evidence-led counterpart to the teacher console. */
@layer components {
  .student-flight-deck { --sf-ink:#133d4b;--sf-teal:#238f8e;--sf-mint:#48c9ad;position:relative;width:calc(100% - 2 * var(--page-gutter));max-width:calc(var(--site-width) - 2 * var(--page-gutter));margin:28px auto 0;padding:clamp(20px,2.8vw,34px);overflow:hidden;color:var(--sf-ink);border:1px solid rgba(35,117,126,.22);background:radial-gradient(circle at 94% 0,rgba(81,198,191,.18),transparent 27%),linear-gradient(rgba(35,117,126,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(35,117,126,.045) 1px,transparent 1px),linear-gradient(145deg,#f6fcfa,#eaf6f4 63%,#e4f0f3);background-size:auto,32px 32px,32px 32px,auto;box-shadow:12px 14px 0 rgba(28,103,111,.09),0 24px 60px rgba(28,78,89,.08)}
