/* Guangguang teaching copilot — a contextual instrument bay, not a generic chat bubble. */
@layer components {
  .teacher-guangguang-trigger { position: fixed; z-index: 82; right: 24px; bottom: 20px; min-width: 195px; height: 66px; display: grid; grid-template-columns: 67px 1fr 33px; align-items: center; gap: 7px; padding: 0 9px 0 0; overflow: visible; color: #dff7ff; border: 1px solid rgba(120, 221, 255, .5); background: linear-gradient(100deg, rgba(8, 29, 47, .97), rgba(12, 49, 72, .97)); box-shadow: 0 13px 45px rgba(0, 0, 0, .38), 0 0 24px rgba(120, 221, 255, .12), inset 0 0 18px rgba(120, 221, 255, .06); cursor: pointer; transition: border-color .2s ease, transform .2s ease, opacity .2s ease; }
  .teacher-guangguang-trigger::before, .teacher-guangguang-trigger::after { content: ""; position: absolute; pointer-events: none; }
  .teacher-guangguang-trigger::before { top: -5px; right: 13px; left: 70px; height: 1px; opacity: .6; background: linear-gradient(90deg, transparent, var(--tc-cyan), transparent); box-shadow: 0 0 9px var(--tc-cyan); }
  .teacher-guangguang-trigger::after { inset: 4px; border: 1px solid rgba(120, 221, 255, .08); }
  .teacher-guangguang-trigger:hover { border-color: var(--tc-cyan); transform: translateY(-3px); }
  .teacher-guangguang-trigger.is-open { opacity: 0; pointer-events: none; transform: translateY(8px); }
  .teacher-guangguang-trigger > .orange-cat-avatar { width: 73px; height: 73px; margin: -13px 0 -5px -4px; }
  .teacher-guangguang-trigger > span { position: relative; z-index: 2; display: grid; justify-items: start; gap: 2px; }
  .teacher-guangguang-trigger > span small { color: var(--tc-cyan); font: 700 7px var(--mono); letter-spacing: .1em; }
  .teacher-guangguang-trigger > span b { font: 700 14px var(--serif); }
  .teacher-guangguang-trigger > i { position: relative; z-index: 2; width: 29px; height: 29px; display: grid; place-items: center; color: #061a29; border-radius: 50%; background: var(--tc-cyan); box-shadow: 0 0 14px rgba(120, 221, 255, .3); font-style: normal; }

  .teacher-guangguang-scrim { position: fixed; z-index: 70; inset: 0; border: 0; background: rgba(1, 8, 15, .38); backdrop-filter: blur(2px); cursor: default; animation: teacher-copilot-fade .2s ease both; }
  .teacher-guangguang-panel { position: fixed; z-index: 80; top: 14px; right: 14px; bottom: 14px; width: min(430px, calc(100vw - 28px)); display: grid; grid-template-rows: auto auto minmax(0, auto) minmax(240px, 1fr) auto; overflow: hidden; color: var(--tc-text); border: 1px solid var(--tc-line-bright); background: radial-gradient(circle at 72% -6%, rgba(120, 221, 255, .15), transparent 24%), linear-gradient(180deg, rgba(10, 34, 54, .99), rgba(5, 20, 34, .995)); box-shadow: -22px 0 70px rgba(0, 0, 0, .5), 0 0 42px rgba(120, 221, 255, .1), inset 0 0 45px rgba(38, 125, 166, .04); opacity: 0; pointer-events: none; transform: translateX(calc(100% + 28px)); transition: opacity .24s ease, transform .32s cubic-bezier(.2,.75,.25,1); }
  .teacher-guangguang-panel::before { content: ""; position: absolute; z-index: -1; inset: 0; opacity: .22; pointer-events: none; background-image: linear-gradient(rgba(120, 221, 255, .06) 1px, transparent 1px), linear-gradient(90deg, rgba(120, 221, 255, .05) 1px, transparent 1px); background-size: 27px 27px; mask-image: linear-gradient(#000, transparent 80%); }
  .teacher-guangguang-panel::after { content: ""; position: absolute; top: -20%; left: 0; width: 1px; height: 28%; opacity: .8; background: var(--tc-cyan); box-shadow: 0 0 16px var(--tc-cyan); animation: teacher-copilot-scan 4.8s linear infinite; }
  .teacher-guangguang-panel.is-open { opacity: 1; pointer-events: auto; transform: none; }
  .teacher-guangguang-header { min-height: 91px; display: grid; grid-template-columns: 73px 1fr auto; align-items: center; gap: 10px; padding: 10px 14px 8px 7px; border-bottom: 1px solid var(--tc-line); background: linear-gradient(90deg, rgba(120, 221, 255, .07), transparent); }
  .teacher-guangguang-avatar { width: 71px; height: 71px; display: grid; place-items: center; overflow: hidden; border: 1px solid rgba(120, 221, 255, .25); border-radius: 50%; background: radial-gradient(circle, rgba(120, 221, 255, .12), transparent 68%); }
  .teacher-guangguang-avatar > .orange-cat-avatar { width: 76px; height: 68px; margin-top: 8px; }
  .teacher-guangguang-header > div:nth-child(2) { display: grid; gap: 2px; }
  .teacher-guangguang-header > div:nth-child(2) > span { color: var(--tc-cyan); font: 700 7px var(--mono); letter-spacing: .13em; }
  .teacher-guangguang-header h2 { font: 700 19px var(--serif); }
