  .teacher-guangguang-header p i { width: 5px; height: 5px; border-radius: 50%; background: var(--tc-green); box-shadow: 0 0 8px var(--tc-green); animation: teacher-signal-pulse 1.8s ease-in-out infinite; }
  .teacher-guangguang-header > button { width: 34px; height: 34px; display: grid; place-items: center; color: #749daf; border: 1px solid var(--tc-line); background: rgba(120, 221, 255, .03); cursor: pointer; }
  .teacher-guangguang-header > button:hover { color: var(--tc-cyan); border-color: var(--tc-line-bright); }
  .teacher-guangguang-boundary { min-height: 48px; display: flex; align-items: center; gap: 9px; padding: 8px 14px; color: var(--tc-amber); border-bottom: 1px solid rgba(255, 211, 106, .16); background: rgba(255, 211, 106, .035); }
