  .teacher-guangguang-insight-head { width: 100%; min-height: 57px; display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 9px 12px; color: #cce8f2; text-align: left; border: 0; background: linear-gradient(90deg, rgba(120, 221, 255, .065), transparent); cursor: pointer; }
  .teacher-guangguang-insight-head > span { min-width: 0; display: grid; gap: 3px; }
  .teacher-guangguang-insight-head small { color: var(--tc-cyan); font: 700 7px var(--mono); letter-spacing: .1em; }
  .teacher-guangguang-insight-head b { overflow: hidden; font: 700 13px var(--serif); text-overflow: ellipsis; white-space: nowrap; }
  .teacher-guangguang-insight-head svg { flex: 0 0 auto; color: #6d9aad; transition: transform .2s ease; }
  .teacher-guangguang-insight-head svg.is-rotated { transform: rotate(180deg); }
  .teacher-guangguang-insight-body { padding: 0 12px 12px; border-top: 1px solid rgba(120, 221, 255, .09); animation: teacher-copilot-body .22s ease both; }
  .teacher-guangguang-insight-body > p { padding: 10px 0 8px; color: #91afbd; font-size: 9px; line-height: 1.65; }
  .teacher-guangguang-insight-body > div:nth-of-type(1) { display: grid; gap: 5px; }
  .teacher-guangguang-insight-body > div:nth-of-type(1) > span { display: flex; align-items: flex-start; gap: 7px; color: #6e93a5; font-size: 8px; line-height: 1.45; }
  .teacher-guangguang-insight-body > div:nth-of-type(1) > span i { width: 4px; height: 4px; flex: 0 0 auto; margin-top: 4px; border-radius: 50%; background: var(--tc-cyan); box-shadow: 0 0 7px var(--tc-cyan); }
  .teacher-guangguang-insight-body > blockquote { display: flex; gap: 9px; margin-top: 10px; padding: 9px 10px; color: var(--tc-amber); border-left: 2px solid var(--tc-amber); background: rgba(255, 211, 106, .045); }
  .teacher-guangguang-insight-body > blockquote svg { flex: 0 0 auto; margin-top: 1px; }
  .teacher-guangguang-insight-body > blockquote span { display: grid; gap: 3px; color: #a8ad98; font-size: 8px; line-height: 1.55; }
  .teacher-guangguang-insight-body > blockquote small { color: #d6c783; font: 700 7px var(--mono); letter-spacing: .08em; }
  .teacher-guangguang-broadcast { margin-top: 9px; padding: 10px; border: 1px solid rgba(85, 229, 193, .18); background: rgba(85, 229, 193, .035); }
  .teacher-guangguang-broadcast > span { display: flex; align-items: center; gap: 6px; color: var(--tc-green); font: 700 7px var(--mono); letter-spacing: .08em; }
  .teacher-guangguang-broadcast > p { margin-top: 6px; color: #a9c9c2; font-size: 8px; line-height: 1.55; }
  .teacher-guangguang-broadcast > button { min-height: 31px; display: inline-flex; align-items: center; gap: 5px; margin-top: 8px; padding: 0 10px; color: #05261f; border: 1px solid var(--tc-green); background: var(--tc-green); font-size: 8px; font-weight: 800; cursor: pointer; }
  .teacher-guangguang-broadcast > small { display: flex; align-items: center; gap: 4px; margin-top: 7px; color: var(--tc-green); font-size: 7px; }

  .teacher-guangguang-dialogue { min-height: 0; display: grid; grid-template-rows: auto auto minmax(78px, 1fr) auto; margin: 10px; overflow: hidden; border: 1px solid var(--tc-line); background: rgba(3, 16, 28, .66); }
  .teacher-guangguang-dialogue > header { min-height: 47px; display: flex; align-items: center; gap: 8px; padding: 8px 11px; color: var(--tc-cyan); border-bottom: 1px solid var(--tc-line); }
  .teacher-guangguang-dialogue > header > span { display: grid; gap: 1px; }
  .teacher-guangguang-dialogue > header b { color: #c6e2ec; font-size: 10px; }
