  .teacher-guangguang-chips button:hover { color: var(--tc-cyan); border-color: var(--tc-line-bright); }
  .teacher-guangguang-messages { min-height: 0; overflow-y: auto; padding: 10px; scrollbar-color: rgba(120, 221, 255, .2) transparent; }
  .teacher-guangguang-welcome { display: flex; align-items: flex-start; gap: 8px; padding: 9px; color: var(--tc-cyan); border: 1px dashed rgba(120, 221, 255, .17); background: rgba(120, 221, 255, .025); }
  .teacher-guangguang-welcome svg { flex: 0 0 auto; }
  .teacher-guangguang-welcome p { color: #789dad; font-size: 8px; line-height: 1.6; }
  .teacher-guangguang-messages article { display: flex; align-items: flex-end; gap: 6px; margin-top: 9px; }
  .teacher-guangguang-messages article.role-teacher { justify-content: flex-end; }
  .teacher-guangguang-messages article > .orange-cat-avatar { width: 42px; height: 39px; flex: 0 0 auto; }
  .teacher-guangguang-messages article > div { max-width: 84%; }
