@layer polish {
  @keyframes teacher-command-fade { from { opacity: 0; } to { opacity: 1; } }
  @keyframes teacher-command-enter { from { opacity: 0; transform: translateY(-9px) scale(.985); } to { opacity: 1; transform: none; } }
  @keyframes teacher-detail-enter { from { opacity: 0; transform: translateX(32px); } to { opacity: 1; transform: none; } }
}

@layer responsive {
  @media (max-width: 1180px) {
    .teacher-command-trigger { min-width: 42px; width: 42px; grid-template-columns: 1fr; place-items: center; padding: 0; }
    .teacher-command-trigger span, .teacher-command-trigger kbd { display: none; }
    .teacher-weekly-schedule > div { grid-template-columns: repeat(2,1fr); }
    .teacher-weekly-schedule > div > a { min-height: 110px; grid-column: 1/-1; border-top: 1px solid var(--tc-line); }
    .teacher-blueprint-flow { grid-template-columns: 1fr 1fr; }
    .teacher-blueprint-flow article:nth-child(2) { border-right: 0; }
    .teacher-blueprint-flow article:nth-child(-n+2) { border-bottom: 1px solid var(--tc-line); }
  }
  @media (max-width: 900px) {
    .teacher-header-actions { margin-left: auto; }
    .teacher-data-toolbar { flex-wrap: wrap; }
    .teacher-data-toolbar > span { width: 100%; margin: 0; padding: 2px 3px; }
  }
  @media (max-width: 650px) {
    .teacher-header-actions { gap: 0; }
    .teacher-command-overlay { padding: 7px; }
    .teacher-command-dialog { max-height: calc(100dvh - 14px); }
    .teacher-attention-rail, .teacher-live-attention { grid-template-columns: 32px 1fr; }
    .teacher-attention-rail > a, .teacher-live-attention > button { grid-column: 2; justify-self: start; }
    .teacher-weekly-schedule > div { grid-template-columns: 1fr; }
    .teacher-weekly-schedule article { min-height: 150px; border-right: 0; border-bottom: 1px solid var(--tc-line); }
    .teacher-weekly-schedule > div > a { grid-column: auto; }
    .teacher-data-toolbar { display: grid; grid-template-columns: 1fr; }
    .teacher-data-toolbar label, .teacher-data-toolbar label:nth-child(2) { min-width: 0; width: 100%; }
    .teacher-class-detail-kpis { grid-template-columns: 1fr; }
    .teacher-class-detail-kpis div { min-height: 72px; border-right: 0; border-bottom: 1px solid var(--tc-line); }
    .teacher-class-detail-groups > div { grid-template-columns: 1fr; }
    .teacher-class-detail > footer { display: grid; }
    .teacher-inquiry-protocol { grid-template-columns: 1fr; }
    .teacher-inquiry-protocol > header { grid-column: auto; }
    .teacher-lesson-queue > div > article { grid-template-columns: 4px minmax(0,1fr); }
    .teacher-lesson-queue article > strong { grid-column: 2; }
    .teacher-lesson-row-actions { grid-column: 2; }
    .teacher-blueprint-flow { grid-template-columns: 1fr; }
    .teacher-blueprint-flow article { min-height: 130px; border-right: 0; border-bottom: 1px solid var(--tc-line); }
    .teacher-blueprint-flow article:not(:last-child)::after { top: auto; right: 20px; bottom: -7px; content: "↓"; }
    .teacher-lesson-blueprint > footer { align-items: stretch; flex-direction: column; }
    .teacher-report-diagnostic { grid-template-columns: 1fr; }
  }
  @media (prefers-reduced-motion: reduce) {
    .teacher-command-overlay, .teacher-command-dialog, .teacher-class-detail { animation: none !important; }
  }
}

