  .notebook-cloud-strip{width:calc(100% - 2 * var(--page-gutter));max-width:calc(var(--site-width) - 2 * var(--page-gutter));min-height:100px;display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:22px;margin:14px auto 0;padding:16px 20px;color:#dff4ef;border:1px solid #315e65;background:linear-gradient(100deg,#103642,#154954);box-shadow:6px 6px 0 rgba(16,54,66,.1)}.notebook-cloud-strip > header{display:flex;align-items:center;gap:11px}.notebook-cloud-strip > header > i{width:42px;height:42px;display:grid;place-items:center;color:#61d9c1;border:1px solid rgba(97,217,193,.28);font-style:normal}.notebook-cloud-strip > header span{display:grid;gap:3px}.notebook-cloud-strip header small{color:#61d9c1;font:700 7px var(--mono);letter-spacing:.08em}.notebook-cloud-strip header b{font-size:11px}.notebook-cloud-strip header p{color:#86a9aa;font-size:8px}.notebook-cloud-strip > div{display:flex;border:1px solid rgba(97,217,193,.13)}.notebook-cloud-strip article{min-width:88px;display:grid;grid-template-columns:19px auto;align-items:center;gap:4px;padding:9px 10px;border-right:1px solid rgba(97,217,193,.12);color:#61d9c1}.notebook-cloud-strip article:last-child{border-right:0}.notebook-cloud-strip article strong{font:800 15px var(--mono)}.notebook-cloud-strip article span{grid-column:1/-1;color:#7da1a2;font-size:7px}.notebook-cloud-strip > a{min-height:38px;display:flex;align-items:center;gap:6px;padding:0 10px;color:#123c43;background:#61d9c1;font-size:8px;font-weight:900;white-space:nowrap}

  .notebook-workspace { width: calc(100% - 2 * var(--page-gutter)); max-width: calc(var(--site-width) - 2 * var(--page-gutter)); display: grid; grid-template-columns: 330px minmax(0,1fr); align-items: start; margin: 58px auto 0; border: 1px solid #b8b1a3; background: #f3eee3; box-shadow: 12px 12px 0 rgba(25,57,65,.08); }
  .notebook-activity-rail { position: sticky; top: 102px; max-height: calc(100vh - 125px); overflow: auto; border-right: 1px solid #b8b1a3; scrollbar-width: thin; scrollbar-color: #8a9d98 transparent; }
  .notebook-activity-rail > header { position: sticky; z-index: 2; top: 0; padding: 24px 22px 20px; border-bottom: 1px solid #b8b1a3; background: #173847; }
