  .notebook-activity-list button > span { min-width: 0; display: grid; gap: 3px; }
  .notebook-activity-list small { overflow: hidden; color: #849092; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
  .notebook-activity-list strong { font-size: 14px; }
  .notebook-activity-list em { color: #7c8988; font-size: 10px; font-style: normal; }
  .notebook-loading,.notebook-empty-rail { min-height: 230px; display: grid; place-content: center; justify-items: center; gap: 8px; padding: 24px; color: #687b7d; text-align: center; }
