  .notebook-paper { min-width: 0; min-height: 850px; padding: 34px 38px 38px; background-color: var(--paper); background-image: linear-gradient(rgba(119,139,137,.15) 1px,transparent 1px); background-size: 100% 32px; }
  .notebook-paper-heading { --notebook-accent: #57b8a7; display: flex; align-items: center; justify-content: space-between; gap: 25px; padding: 4px 2px 26px 18px; border-bottom: 3px solid var(--notebook-accent); border-left: 6px solid var(--notebook-accent); }
