  .notebook-auto-evidence blockquote small { display: block; margin-top: 3px; color: #8c9995; font-size: 9px; }
  .notebook-writing-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 22px; }
  .notebook-writing-grid label { min-width: 0; min-height: 235px; display: grid; grid-template-rows: auto 1fr; padding: 17px; border: 1px solid #c5bcae; background: rgba(255,252,244,.88); box-shadow: 5px 5px 0 rgba(49,72,72,.045); }
  .notebook-writing-grid label > span { display: grid; grid-template-columns: 23px 25px 1fr; align-items: center; gap: 7px; padding-bottom: 11px; border-bottom: 1px solid #d3ccbf; }
  .notebook-writing-grid label > span svg { color: #b45a36; }
  .notebook-writing-grid label > span b { color: #a8aaa4; font-size: 10px; }
  .notebook-writing-grid label > span strong { font-size: 15px; }
  .notebook-writing-grid label > span small { grid-column: 3; color: #87918f; font-size: 9px; }
  .notebook-writing-grid textarea { width: 100%; min-height: 150px; padding: 11px 4px 0; resize: vertical; color: #40585d; border: 0; outline: 0; background: repeating-linear-gradient(transparent 0,transparent 30px,rgba(98,123,121,.19) 31px,transparent 32px); font-size: 14px; font-weight: 700; line-height: 32px; }
  .notebook-writing-grid textarea:focus { background-color: rgba(246,226,169,.14); }
  .notebook-writing-grid textarea::placeholder { color: #a9aaa4; font-weight: 500; }
  .notebook-paper-actions { display: flex; align-items: center; gap: 9px; margin-top: 24px; padding-top: 18px; border-top: 1px solid #c5bdae; }
  .notebook-paper-actions button { min-height: 42px; display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding: 0 13px; color: #526667; border: 1px solid #aeb3aa; background: #f8f2e6; cursor: pointer; font-size: 11px; font-weight: 800; }
  .notebook-paper-actions button:hover { color: #a64d2c; border-color: #d47c50; }
  .notebook-paper-actions button.danger { color: #a95345; }
  .notebook-paper-actions > span { flex: 1; color: #8b918c; font-size: 9px; text-align: right; }
  .notebook-paper-actions button.primary { min-width: 150px; color: #eff8f3; border-color: #173847; background: #173847; box-shadow: 4px 4px 0 #df8a43; }
  .notebook-paper-actions button.primary:disabled { opacity: .45; cursor: not-allowed; box-shadow: none; }
  .notebook-paper-empty { min-height: 700px; display: grid; place-content: center; justify-items: center; gap: 10px; text-align: center; }
  .notebook-paper-empty svg { color: #d47a42; }
  .notebook-paper-empty h2 { max-width: 500px; color: #274550; font-size: 28px; }
  .notebook-paper-empty p { color: #77898a; }
  .notebook-paper-empty a { display: inline-flex; align-items: center; gap: 7px; margin-top: 10px; padding: 11px 15px; color: white; background: #173847; }

  .notebook-record-library { width: calc(100% - 2 * var(--page-gutter)); max-width: calc(var(--site-width) - 2 * var(--page-gutter)); margin: 76px auto 0; }
  .notebook-record-library > header { display: grid; grid-template-columns: 1fr 1fr; align-items: end; gap: 50px; padding-bottom: 22px; border-bottom: 1px solid #aca79d; }
  .notebook-record-library > header span { color: #b85e3b; font-size: 10px; font-weight: 800; letter-spacing: .14em; }
  .notebook-record-library > header h2 { margin-top: 5px; font-size: 35px; }
  .notebook-record-library > header p { max-width: 560px; justify-self: end; color: #657a7c; line-height: 1.75; }
  .notebook-record-library > div { display: grid; grid-template-columns: repeat(3,1fr); margin-top: 25px; border-top: 1px solid #b7b0a3; border-left: 1px solid #b7b0a3; }
  .notebook-record-library button { position: relative; min-height: 225px; padding: 25px; color: #2b4952; border-right: 1px solid #b7b0a3; border-bottom: 1px solid #b7b0a3; background: #f9f3e7; cursor: pointer; text-align: left; }
  .notebook-record-library button:hover { z-index: 2; background: #fff9ec; transform: translate(-3px,-3px); box-shadow: 6px 6px 0 #d9914b; }
  .notebook-record-library button > b { position: absolute; top: 18px; right: 20px; color: rgba(30,57,66,.12); font-size: 39px; }
  .notebook-record-library button > small { color: #9a744d; font-size: 9px; }
  .notebook-record-library h3 { max-width: 80%; margin-top: 28px; font-size: 20px; }
  .notebook-record-library p { display: -webkit-box; margin-top: 9px; overflow: hidden; color: #728183; font-size: 12px; line-height: 1.65; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
  .notebook-record-library button > span { display: flex; align-items: center; gap: 7px; margin-top: 20px; color: #a9502f; font-size: 10px; font-weight: 800; }
}

@layer responsive {
  @media (max-width: 1180px) {
    .dashboard-notebook-entry { grid-template-columns: 110px 1fr auto; }
    .dashboard-notebook-entry > aside { display: none; }
    .notebook-hero { grid-template-columns: 1fr 330px; gap: 40px; }
    .notebook-workspace { grid-template-columns: 280px minmax(0,1fr); }
    .notebook-paper { padding-inline: 25px; }
  }
  @media (max-width: 900px) {
    .dashboard-notebook-entry { grid-template-columns: 92px 1fr; }
    .dashboard-notebook-icon { width: 86px; height: 105px; }
    .dashboard-notebook-entry > a { grid-column: 2; justify-self: start; }
    .notebook-hero { grid-template-columns: 1fr; padding: 42px; }
    .notebook-hero > aside { min-height: 0; }
    .notebook-cloud-strip{grid-template-columns:1fr auto}.notebook-cloud-strip > div{grid-row:2;grid-column:1/-1}.notebook-cloud-strip article{flex:1}
    .notebook-workspace { grid-template-columns: 1fr; }
    .notebook-activity-rail { position: relative; top: auto; max-height: none; border-right: 0; border-bottom: 1px solid #b8b1a3; }
    .notebook-activity-list { display: flex; overflow-x: auto; }
    .notebook-activity-list button { flex: 0 0 265px; border-right: 1px solid #ccc5b8; border-bottom: 0; }
    .notebook-record-library > div { grid-template-columns: 1fr 1fr; }
  }
  @media (max-width: 640px) {
    .dashboard-notebook-entry { width: calc(100% - 24px); grid-template-columns: 1fr; gap: 17px; padding: 23px; }
    .dashboard-notebook-icon { display: none; }
    .dashboard-notebook-entry > a { grid-column: auto; justify-self: stretch; }
    .notebook-back-link { font-size: 0; padding-inline: 11px; }
    .notebook-hero,.notebook-workspace,.notebook-record-library,.notebook-cloud-strip { width: calc(100% - 24px); }
    .notebook-hero { margin-top: 18px; padding: 30px 22px; }
    .notebook-hero h1 { font-size: 35px; }
    .notebook-hero p { font-size: 14px; }
    .notebook-cloud-strip{grid-template-columns:1fr;padding:15px}.notebook-cloud-strip > div{grid-row:auto;grid-column:auto}.notebook-cloud-strip article{min-width:0;padding:8px 5px}.notebook-cloud-strip > a{justify-content:center}
    .notebook-paper { min-height: 0; padding: 24px 14px; }
    .notebook-paper-heading { align-items: flex-start; flex-direction: column; }
    .notebook-writing-grid { grid-template-columns: 1fr; }
    .notebook-writing-grid label { min-height: 215px; }
    .notebook-paper-actions { align-items: stretch; flex-direction: column; }
    .notebook-paper-actions > span { order: -1; text-align: left; }
    .notebook-record-library > header { grid-template-columns: 1fr; gap: 13px; }
    .notebook-record-library > div { grid-template-columns: 1fr; }
  }
}

/* Cross-page contextual physics instrumentation. */
@layer components {
  .physics-context-layer { --context-accent: #e79a43; --context-cool: #55d7c0; position: fixed; z-index: 20; inset: 0; overflow: hidden; pointer-events: none; font-family: var(--kai); }
  .physics-context-layer.context-light { --context-accent: #f3b94f; --context-cool: #40d5cb; }
  .physics-context-layer.context-sound { --context-accent: #65b8ee; --context-cool: #72ddd2; }
  .physics-context-layer.context-mechanics { --context-accent: #e4a746; --context-cool: #7ec49b; }
  .physics-context-layer.context-circuit { --context-accent: #f2775f; --context-cool: #6dd8c2; }
  .physics-context-layer.context-thermal { --context-accent: #ef873e; --context-cool: #f2c55a; }
  .physics-context-layer.context-measurement { --context-accent: #a890e8; --context-cool: #6fc7d0; }

  .physics-context-rail { position: fixed; z-index: 2; top: 76px; right: 0; bottom: 0; width: 22px; display: flex; flex-direction: column; justify-content: space-around; padding-block: 8px; border-left: 1px solid color-mix(in srgb,var(--context-accent) 46%,transparent); background: linear-gradient(90deg,transparent,rgba(11,38,46,.08)); opacity: .7; }
  .physics-context-rail::before { content: "Δ / SCALE"; position: absolute; top: 9px; right: 3px; color: color-mix(in srgb,var(--context-accent) 78%,#24434a); font: 900 7px var(--mono); letter-spacing: .12em; writing-mode: vertical-rl; }
  .physics-context-rail i { position: relative; width: 8px; height: 1px; margin-left: auto; background: color-mix(in srgb,var(--context-cool) 58%,#43616a); }
  .physics-context-rail i.major { width: 16px; height: 2px; background: var(--context-accent); }
  .physics-context-rail i b { position: absolute; right: 19px; top: -6px; color: color-mix(in srgb,var(--context-accent) 70%,#38545a); font: 800 7px var(--mono); font-style: normal; }

  .physics-context-plate { position: fixed; z-index: 4; right: 37px; bottom: 22px; width: 224px; min-height: 126px; padding: 13px 14px 11px; color: #eaf4ef; border: 1px solid color-mix(in srgb,var(--context-accent) 65%,#31525a); border-top: 4px solid var(--context-accent); background: linear-gradient(135deg,rgba(18,52,61,.93),rgba(9,35,43,.88)); box-shadow: 6px 6px 0 color-mix(in srgb,var(--context-accent) 25%,transparent),0 18px 42px rgba(5,25,31,.15); backdrop-filter: blur(6px); opacity: .88; pointer-events:auto; transition:width .2s ease,min-height .2s ease,padding .2s ease,opacity .2s ease,box-shadow .2s ease; }
  .physics-context-plate.is-collapsed { width:42px; min-height:42px; padding:0; overflow:hidden; border-top-width:1px; background:rgba(10,38,47,.72); box-shadow:3px 3px 0 color-mix(in srgb,var(--context-accent) 24%,transparent),0 9px 22px rgba(5,25,31,.12); opacity:.62; }
  .physics-context-plate.is-collapsed:hover { opacity:.92; transform:translateY(-1px); }
  body:has(.page-intro-trigger) .physics-context-plate { bottom:82px; }
  .physics-context-plate::before { content: ""; position: absolute; inset: 7px; border: 1px solid rgba(255,255,255,.055); }
  .physics-context-plate.is-collapsed::before,.physics-context-plate.is-collapsed .physics-context-plate-body { display:none; }
  .physics-context-toggle { position:absolute;z-index:3;top:7px;right:7px;width:27px;height:27px;display:grid;place-items:center;padding:0;color:color-mix(in srgb,var(--context-accent) 74%,white);border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.035);cursor:pointer; }
  .physics-context-toggle:hover { color:white;border-color:var(--context-accent);background:color-mix(in srgb,var(--context-accent) 14%,transparent); }
  .physics-context-plate.is-collapsed .physics-context-toggle { inset:0;width:42px;height:42px;border:0;background:transparent; }
  .physics-context-plate-body { position:relative;z-index:1; }
  .physics-context-plate-body > span { display: flex; align-items: center; gap: 6px; padding-right:30px; color: color-mix(in srgb,var(--context-accent) 80%,white); font: 900 8px var(--mono); letter-spacing: .09em; }
  .physics-context-plate-body > span i { width: 6px; height: 6px; border-radius: 50%; background: var(--context-cool); box-shadow: 0 0 0 4px color-mix(in srgb,var(--context-cool) 18%,transparent); animation: context-live-signal 1.8s ease-out infinite; }
  .physics-context-plate-body > strong { display: block; margin-top: 7px; font-size: 15px; letter-spacing: .05em; }
  .physics-context-plate-body > code { display: block; margin-top: 5px; color: #fff0bd; font: 900 17px var(--kai); }
  .physics-context-plate-body > small { display: block; margin-top: 3px; color: #9db5b3; font-size: 9px; font-weight: 700; }
  .physics-context-plate-body > div { display: flex; gap: 4px; margin-top: 8px; }
  .physics-context-plate-body > div b { min-width: 25px; height: 20px; display: grid; place-items: center; color: #b9cfca; border: 1px solid #4c6a70; background: rgba(255,255,255,.025); font: 800 8px var(--mono); }

  .physics-context-sketch { position: fixed; z-index: 1; top: 96px; right: 35px; width: min(245px,20vw); height: auto; overflow: visible; color: var(--context-cool); opacity: .14; filter: drop-shadow(0 0 8px color-mix(in srgb,var(--context-cool) 28%,transparent)); }
  .physics-context-sketch path,.physics-context-sketch ellipse,.physics-context-sketch circle { vector-effect: non-scaling-stroke; }
  .context-grid path { fill: none; stroke: currentColor; stroke-width: .55; stroke-dasharray: 2 5; opacity: .42; }
  .context-mixed ellipse { fill: none; stroke: var(--context-cool); stroke-width: 1.5; }
  .context-mixed > circle:not(.context-particle) { fill: color-mix(in srgb,var(--context-accent) 45%,transparent); stroke: var(--context-accent); stroke-width: 2; }
  .context-particle { fill: var(--context-accent); animation: context-particle-pulse 2.4s ease-in-out infinite alternate; }
  .context-particle.p2 { animation-delay: -.8s; }.context-particle.p3 { animation-delay: -1.6s; }
  .context-axis,.context-beam,.context-force,.context-wire,.context-device,.context-battery,.context-resistor,.context-beaker,.context-curve,.context-balance,.context-pan,.context-cylinder { fill: none; stroke: currentColor; stroke-width: 2; }
  .context-optic { fill: color-mix(in srgb,var(--context-cool) 18%,transparent); stroke: var(--context-cool); stroke-width: 2; }
  .context-energy { fill: none; stroke: var(--context-accent); stroke-width: 2.5; stroke-dasharray: 8 6; animation: context-energy-flow 2.1s linear infinite; }
  .context-energy.e2 { stroke: var(--context-cool); animation-duration: 2.7s; }
  .context-light circle { fill: var(--context-accent); }
  .context-sound .sound-wave { stroke-width: 2.4; animation-duration: 1.65s; }
  .context-sound .second { stroke: var(--context-cool); animation-delay: -.6s; }
  .context-fulcrum { fill: color-mix(in srgb,var(--context-accent) 18%,transparent); stroke: var(--context-accent); stroke-width: 2; }
  .context-force { stroke: var(--context-accent); animation: context-force-pulse 1.5s ease-in-out infinite alternate; }
  .context-force.f2 { stroke: var(--context-cool); animation-delay: -.75s; }
  .context-wire { stroke: var(--context-cool); }
  .context-battery,.context-resistor { stroke: var(--context-accent); }
  .context-charge { fill: #fff0ad; filter: drop-shadow(0 0 5px var(--context-accent)); animation: context-charge-move 1.7s ease-in-out infinite; }
  .context-water { fill: color-mix(in srgb,var(--context-cool) 22%,transparent); stroke: var(--context-cool); stroke-width: 1.5; }
  .context-heat { fill: var(--context-accent); animation: context-heat-rise 1.9s ease-out infinite; }
  .context-heat.h2 { animation-delay: -.65s; }.context-heat.h3 { animation-delay: -1.3s; }
  .context-curve { stroke: var(--context-accent); stroke-dasharray: 7 4; animation: context-energy-flow 2.5s linear infinite; }
  .context-measurement .context-pan { fill: color-mix(in srgb,var(--context-accent) 10%,transparent); }
  .context-measurement .context-cylinder { stroke: var(--context-accent); }

  .physics-context-scan { position: fixed; z-index: 0; top: 76px; right: 22px; bottom: 0; width: 1px; background: linear-gradient(transparent,var(--context-cool),transparent); opacity: .16; animation: context-scan 7s ease-in-out infinite; transform-origin: top; }
  @keyframes context-live-signal { 0% { box-shadow: 0 0 0 0 color-mix(in srgb,var(--context-cool) 30%,transparent); } 75%,100% { box-shadow: 0 0 0 8px transparent; } }
