  .harness-session-summary > header > button > svg:last-child { color: #758682; transition: transform .2s ease; }
  .harness-session-summary.open > header > button > svg:last-child { transform: rotate(180deg); }
  .harness-session-summary-sheet { padding: 11px; border-top: 1px solid #c7d2cc; background: repeating-linear-gradient(#fffdf7 0,#fffdf7 25px,#dfe7e0 26px); }
  .harness-session-summary-sheet dl { display: grid; gap: 7px; }
  .harness-session-summary-sheet dl > div { display: grid; grid-template-columns: 68px minmax(0,1fr); gap: 8px; padding: 7px 8px; border-left: 3px solid #66ad9e; background: rgba(255,255,255,.9); }
  .harness-session-summary-sheet dt { color: #287365; font-size: 9px; font-weight: 900; letter-spacing: .05em; }
