  .harness-session-summary-sheet > footer { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 10px; padding-top: 9px; border-top: 1px dashed #aebdb6; }
  .harness-session-summary-sheet > footer small { display: inline-flex; align-items: flex-start; gap: 5px; color: #7e8c88; font-size: 8px; line-height: 1.4; }
  .harness-session-summary-sheet > footer small svg { flex: 0 0 auto; color: #399682; }
  .harness-session-summary-sheet > footer button { min-height: 32px; display: inline-flex; flex: 0 0 auto; align-items: center; gap: 5px; padding: 0 9px; color: white; background: #173847; font-size: 9px; font-weight: 900; cursor: pointer; }
  .harness-session-summary-sheet > footer button:not(:disabled):hover { color: #173847; background: #61d7bf; }
  .harness-session-summary-sheet > footer button:disabled { color: #75837f; background: #d9dfda; cursor: not-allowed; }

  .harness-chat { margin: 13px; overflow: hidden; border: 1px solid #c7c1b5; background: #f6f2e8; box-shadow: 5px 5px 0 rgba(23,56,71,.07); }
  .harness-chat-stream { min-height: 165px; max-height: 315px; display: grid; align-content: start; gap: 12px; padding: 14px; overflow-y: auto; overscroll-behavior: contain; background: radial-gradient(circle at 100% 0,rgba(83,216,192,.09),transparent 27%),#fbf8ef; }
  .harness-message { display: grid; grid-template-columns: 29px minmax(0,1fr); align-items: start; gap: 8px; animation: harness-message-in .2s ease both; }
  .harness-message > i { width: 28px; height: 28px; display: grid; place-items: center; color: #1e7669; border: 1px solid #8dc6ba; border-radius: 50%; background: #e2f3ec; font-style: normal; }
  .harness-message > div { position: relative; padding: 10px 11px 9px; color: #314f56; border: 1px solid #d0cabe; background: white; }
  .harness-message > div::before { content: ""; position: absolute; top: 9px; left: -5px; width: 8px; height: 8px; border-bottom: 1px solid #d0cabe; border-left: 1px solid #d0cabe; background: white; transform: rotate(45deg); }
  .harness-message small { display: block; margin-bottom: 4px; color: #55847d; font-size: 10px; letter-spacing: .04em; }
  .harness-message p { font-size: 13px; line-height: 1.72; }
  .harness-message em { display: flex; align-items: center; gap: 4px; margin-top: 7px; color: #98a29f; font-size: 8px; font-style: normal; letter-spacing: .05em; }
  .harness-message em svg { color: #d48a40; }
  .harness-message.learner { grid-template-columns: minmax(0,1fr) 29px; padding-left: 50px; }
  .harness-message.learner > i { grid-column: 2; grid-row: 1; color: #8a6321; border-color: #d7b86e; background: #fff1c9; }
  .harness-message.learner > div { grid-column: 1; grid-row: 1; color: #253f47; border-color: #b8c9c5; background: #e7f3ee; }
  .harness-message.learner > div::before { right: -5px; left: auto; border: 0; border-top: 1px solid #b8c9c5; border-right: 1px solid #b8c9c5; background: #e7f3ee; }
  .harness-message.learner small { color: #8a6321; text-align: right; }
  .harness-message.welcome > div { border-left: 3px solid #53d8c0; }
  .harness-message.welcome em { color: #9a7a37; }

  .harness-quick-questions { padding: 10px 12px 11px; border-top: 1px solid #d6d0c4; background: #eee9de; }
  .harness-quick-questions > span { color: #788789; font-size: 10px; letter-spacing: .08em; }
  .harness-quick-questions > div { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 7px; }
  .harness-quick-questions button { min-height: 29px; padding: 4px 8px; color: #325c60; border: 1px solid #9eb6b2; background: #faf8f1; cursor: pointer; font-size: 11px; text-align: left; }
  .harness-quick-questions button:hover { color: #0f6b5b; border-color: #4db7a2; background: #e0f3eb; transform: translateY(-1px); }

  .harness-composer { display: grid; grid-template-columns: 1fr auto auto; border-top: 1px solid #bfb9ad; background: #faf7ef; }
  .harness-composer textarea { grid-column: 1/-1; width: 100%; min-height: 76px; padding: 11px 12px; resize: vertical; color: #2a4850; border: 0; border-bottom: 1px solid #d5cfc3; outline: 0; background: white; font-size: 13px; line-height: 1.65; }
  .harness-composer textarea:focus { box-shadow: inset 3px 0 #53d8c0; }
  .harness-draft-intelligence { grid-column: 1/-1; min-height: 39px; display: grid; grid-template-columns: 19px 1fr auto; align-items: center; gap: 6px; padding: 6px 9px; color: #397269; border-bottom: 1px solid #c9d8d2; background: #edf7f2; }
  .harness-draft-intelligence.mode-observation { color: #816324; background: #fff4d5; }
  .harness-draft-intelligence.mode-hypothesis { color: #3a6d8a; background: #e7f5fb; }
  .harness-draft-intelligence.mode-reasoning { color: #32756b; background: #e8f7f2; }
  .harness-draft-intelligence.mode-conclusion { color: #2c6683; background: #e9f6fc; }
  .harness-draft-intelligence.mode-out-of-scope { color: #a0523c; background: #fff0e8; }
  .harness-draft-intelligence > span { min-width: 0; display: grid; gap: 2px; }
  .harness-draft-intelligence strong { font-size: 9px; }
  .harness-draft-intelligence small { overflow: hidden; color: #728580; font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
  .harness-draft-intelligence > b { color: currentColor; font: 900 9px var(--mono); }
  .harness-draft-intelligence > span > i { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 3px; font-style: normal; }
  .harness-draft-intelligence > span > i b { min-height: 18px; display: inline-flex; align-items: center; gap: 3px; padding: 1px 4px; color: #8a8f8c; border: 1px solid #c6ccc7; background: rgba(255,255,255,.66); font-size: 7px; font-weight: 800; }
  .harness-draft-intelligence > span > i b > span { width: 6px; height: 6px; border: 1px solid currentColor; border-radius: 50%; }
  .harness-draft-intelligence > span > i b.passed { color: #327e6d; border-color: #83b9ab; background: #e9f6ef; }
  .harness-evidence-template { grid-column: 1; min-height: 40px; display: inline-flex; align-items: center; justify-content: center; gap: 5px; padding: 0 8px; color: #805d20; border-right: 1px solid #d5cfc3; background: #fff0c7; font-size: 9px; font-weight: 900; cursor: pointer; }
  .harness-evidence-template:hover { color: #173847; background: #f6d57d; }
  .harness-evidence-template.conclusion { color: #275f7a; background: #e0f3fb; }
  .harness-evidence-template.conclusion:hover { color: white; background: #347e9f; }
  .harness-evidence-template.hypothesis { color: #276684; background: #dff3fb; }
  .harness-evidence-template.hypothesis:hover { color: white; background: #327f9f; }
  .harness-evidence-template.reasoning { color: #296e63; background: #e0f5ee; }
  .harness-evidence-template.reasoning:hover { color: white; background: #347f72; }
  @keyframes harness-review-pulse { 0%,100% { opacity: .55; transform: rotate(0); } 50% { opacity: 1; transform: rotate(-25deg); } }
  .harness-composer > button { min-height: 40px; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 0 11px; cursor: pointer; font-size: 11px; }
  .harness-composer > button:disabled { cursor: not-allowed; opacity: .45; }
  .harness-send { color: white; background: #173847; }
  .harness-send.suggested { box-shadow: inset 0 -3px #66e4cb; }
  .harness-send:not(:disabled):hover { color: #66f2d5; }
  .harness-save-observation { color: #526c70; border-left: 1px solid #d5cfc3; background: transparent; }
  .harness-save-observation.suggested { color: #704b16; background: #ffeab4; box-shadow: inset 0 -3px #d69a36; }
  .harness-save-observation:not(:disabled):hover { color: #9b6320; background: #fff0c5; }
  .harness-composer > small { align-self: center; padding: 0 9px; color: #9aa09d; font-size: 9px; white-space: nowrap; }

  .harness-live-insight { width: calc(100% - 26px); display: grid; grid-template-columns: 30px 1fr auto; align-items: start; gap: 9px; margin: 0 13px 9px; padding: 11px; color: #314e54; border: 1px solid #d2bd7d; background: #fff2c9; text-align: left; cursor: pointer; }
  .harness-live-insight > svg { color: #c27a27; }
  .harness-live-insight > span { display: grid; gap: 3px; }
  .harness-live-insight small { color: #9c7c47; font-size: 9px; }
  .harness-live-insight strong { font-size: 12px; }
  .harness-live-insight p { color: #77684e; font-size: 11px; line-height: 1.55; }
  .harness-live-insight > b { padding: 2px 5px; color: white; background: #df745d; font-size: 9px; }
  .harness-live-insight.read { opacity: .72; }
  .harness-dialogue-trace { margin-top: 5px; }
  @keyframes harness-message-in { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }
}

@layer responsive {
  @media (max-width: 640px) {
    .harness-dialogue-panel { inset: 8px; width: auto; }
    .harness-dialogue-context { align-items: flex-start; flex-direction: column; gap: 7px; }
    .harness-dialogue-metrics { display: flex; gap: 12px; }
    .harness-chat { margin: 9px; }
    .harness-chat-stream { max-height: 290px; }
    .harness-message.learner { padding-left: 24px; }
    .harness-composer { grid-template-columns: 1fr 1fr; }
    .harness-composer > small { grid-column: 1/-1; padding: 7px 9px; }
    .harness-session-summary > header > button { grid-template-columns: 22px minmax(0,1fr) auto 15px; }
    .harness-session-summary > header > button > b:first-of-type { display: none; }
    .harness-session-summary-sheet dl > div { grid-template-columns: 1fr; gap: 3px; }
    .harness-session-summary-sheet > footer { align-items: stretch; flex-direction: column; }
    .harness-session-summary-sheet > footer button { justify-content: center; }
    .harness-concept-map-body { grid-template-columns: 1fr; }
    .harness-learning-branch { grid-template-columns: 30px minmax(0,1fr); }
    .harness-learning-branch > button { grid-column: 1/-1; justify-content: center; }
    .harness-concept-map-body > header,.harness-concept-map-body > aside,.harness-concept-map-body > footer { grid-column: 1; }
    .harness-concept-map-body > aside { grid-template-columns: 1fr; }
    .harness-concept-map-body > aside button { grid-column: 1; grid-row: auto; min-height: 30px; justify-content: center; }
  }
}

/* Layout polish v3: one editorial grid across every platform page. */
@layer polish {
  :root {
    --site-width: 1360px;
    --reading-width: 780px;
    --page-gutter: clamp(22px,4vw,56px);
    --section-space: clamp(64px,7vw,104px);
    --panel-shadow: 9px 9px 0 rgba(18,47,57,.075);
  }

  html { scrollbar-gutter: stable; }
  body { overflow-x: clip; }
  #root, .home-page, .explore-page, .science-explore-page, .workbench-page { min-width: 0; }
  :is(h1,h2,h3) { text-wrap: balance; }
  p { text-wrap: pretty; }
  :is(button,a,input,textarea,select) { border-radius: 0; }

  :is(.home-nav,.explore-header) {
    width: 100%;
    border-bottom-color: rgba(18,47,57,.18);
  }
  :is(.home-nav,.explore-header) nav { white-space: nowrap; }
  :is(.home-nav,.explore-header) nav a { min-height: 42px; display: inline-flex; align-items: center; }

  /* Main entrance */
  .home-nav { max-width: var(--site-width); padding-inline: var(--page-gutter); }
  .hero-lab {
    width: 100%;
    max-width: var(--site-width);
    min-height: 650px;
    grid-template-columns: minmax(390px,.84fr) minmax(560px,1.16fr);
    gap: clamp(38px,5vw,76px);
    padding-inline: var(--page-gutter);
  }
  .hero-copy { min-width: 0; padding: 76px 0 82px; }
  .hero-copy h1 { max-width: 720px; line-height: 1.06; }
  .hero-description { max-width: 620px; margin-top: 24px; }
  .hero-actions { flex-wrap: wrap; row-gap: 14px; }
  .entry-model-note { max-width: 680px; }
  .hero-stats { max-width: 650px; }
  .hero-instrument {
    align-self: center;
    min-width: 0;
    min-height: 548px;
    margin-block: 46px;
    border: 1px solid rgba(102,242,213,.2);
    box-shadow: 16px 16px 0 rgba(3,18,24,.13);
  }
  .home-live-physics .canvas-scene-caption { max-width: min(64%,500px); }
  .lab-library { padding-block: var(--section-space); }
  .lab-library > :is(.section-heading,.lab-grid) { width: 100%; max-width: calc(var(--site-width) - 2 * var(--page-gutter)); margin-inline: auto; }
  .section-heading { position: relative; padding-bottom: 25px; }
  .section-heading::after { content: ""; position: absolute; right: 0; bottom: 0; left: 0; height: 1px; background: linear-gradient(90deg,var(--cyan),rgba(255,255,255,.14) 34%,rgba(255,255,255,.06)); }
  .section-heading p { max-width: 560px; justify-self: end; }
  .lab-grid { margin-top: 34px; }
  .lab-card { min-height: 282px; display: flex; flex-direction: column; }
  .lab-card-copy { margin-top: 48px; }
  .lab-card p { max-width: 260px; }
  .lab-status { margin-top: auto; }
  .architecture-band { max-width: var(--site-width); padding: var(--section-space) var(--page-gutter); }
  .architecture-title { padding-bottom: 22px; border-bottom: 1px solid var(--line); }
  .architecture-steps div { min-height: 180px; }

  /* Student discovery overview */
  .explore-header {
    position: sticky;
    z-index: 60;
    top: 0;
    padding-inline: max(var(--page-gutter),calc((100vw - var(--site-width))/2 + var(--page-gutter)));
    box-shadow: 0 8px 22px rgba(19,50,59,.055);
  }
  .discovery-home-hero {
    width: calc(100% - 2 * var(--page-gutter));
    max-width: calc(var(--site-width) - 2 * var(--page-gutter));
    min-height: 420px;
    grid-template-columns: minmax(0,1.05fr) minmax(420px,.95fr);
    gap: clamp(34px,4vw,64px);
    margin-top: 34px;
    padding: clamp(38px,4vw,58px);
  }
  .discovery-home-hero.is-authenticated{min-height:350px;margin-top:24px;padding-block:clamp(31px,3vw,43px);background:linear-gradient(rgba(112,183,181,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(112,183,181,.045) 1px,transparent 1px),radial-gradient(circle at 82% 28%,rgba(54,191,168,.16),transparent 27%),#0c2d38;background-size:34px 34px,34px 34px,auto,auto}.discovery-home-hero.is-authenticated .discovery-home-atlas{min-height:270px}.discovery-home-hero.is-authenticated .discovery-home-copy h1{font-size:clamp(34px,3.5vw,49px)}
  .discovery-home-copy { max-width: 720px; }
  .discovery-home-copy h1 { margin-top: 17px; }
  .discovery-home-copy > span { max-width: 680px; }
  .discovery-home-atlas { width: 100%; min-width: 0; min-height: 310px; }
  .discovery-field-section {
    width: calc(100% - 2 * var(--page-gutter));
    max-width: calc(var(--site-width) - 2 * var(--page-gutter));
    padding-block: clamp(58px,6vw,86px);
  }
  .discovery-section-title { padding-bottom: 28px; border-bottom: 1px solid #bbb6aa; }
  .discovery-section-title p { max-width: 560px; justify-self: end; }
  .discovery-field-grid { margin-top: 28px; }
  .discovery-field-card { min-height: 325px; padding: 29px 30px 27px; }
  .discovery-field-card p { max-width: 330px; }
  .discovery-question-section { padding-block: clamp(64px,7vw,94px); }
  .discovery-question-heading { max-width: 530px; }
  .discovery-question-list a { padding-inline: 4px 10px; }
  .discovery-tool-note {
    width: calc(100% - 2 * var(--page-gutter));
    max-width: calc(var(--site-width) - 2 * var(--page-gutter));
    margin-block: 58px 82px;
  }

  /* Shared field pages: keep hierarchy stable from overview to experiment. */
  .science-header { min-width: 0; }
  .science-header > :is(div,p,a) { min-width: 0; }
  .science-header > p { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .science-layout { align-items: start; }
  .science-nav { min-width: 0; }
  .science-nav > a { border-bottom: 1px solid rgba(137,143,138,.16); }
  .science-nav > a:last-child { border-bottom: 0; }
  .science-nav > a span { min-width: 0; }
  .science-stage { min-width: 0; background: linear-gradient(90deg,rgba(23,56,71,.025) 1px,transparent 1px),#f1ede3; background-size: 38px 100%; }
  .science-module-bar {
    width: 100%;
    max-width: 1180px;
    border-top: 3px solid var(--science-accent);
    box-shadow: var(--panel-shadow);
  }
  .science-module-bar nav { scrollbar-width: thin; scrollbar-color: color-mix(in srgb,var(--science-accent) 60%,#6f7e7f) transparent; }
  .science-module-bar nav button { min-height: 70px; }
  .science-field-context, .science-module-tabs, .science-field-overview, .science-module-experience { width: 100%; }
  .science-field-hero { overflow: hidden; box-shadow: var(--panel-shadow); }
  .science-field-hero > div:first-child { position: relative; z-index: 2; min-width: 0; }
  .science-textbook-chain, .science-curriculum-note { box-shadow: 6px 6px 0 rgba(18,47,57,.045); }
  .science-overview-heading { margin-top: 12px; border-bottom: 1px solid #c6c1b6; }
  .science-module-card-grid { margin-top: 18px; }
  .science-module-card-grid > button { min-width: 0; }
  .science-module-card-grid p { max-width: 470px; }
  .science-module-experience > .science-lab { margin-bottom: 34px; }
  .science-lab, .open-module-intro, .open-experience > :is(.dispersion-guide,.rainbow-life-section,.micro-display-technology,.mirror-life-technology,.black-hole-extension) { box-shadow: var(--panel-shadow); }
  .science-lab > header, .open-module-intro { border-left: 5px solid var(--science-accent); }
  .science-lab > header > div:first-child, .open-module-intro > div:first-child { min-width: 0; }
  .science-lab > header p, .open-module-intro p { max-width: var(--reading-width); }
  .science-controls, .open-control-deck, .bench-control-grid { align-items: stretch; }
  :is(.science-range,.science-result-cell,.open-range,.observation-output) { min-width: 0; }
  :is(.science-range,.open-range) input[type="range"] { width: 100%; }
  .science-experiment-guide, .science-life-application, .dispersion-guide, .rainbow-life-section { margin-top: 30px; }
  :is(.science-experiment-guide,.science-life-application,.dispersion-guide,.rainbow-life-section) > header { border-left: 5px solid var(--science-accent); }

  /* Optics keeps the same structure as the other five fields. */
  .optics-structure-stage .explore-module-content { min-width: 0; }
  .island-overview, .open-experience { width: 100%; }
  .island-intro { box-shadow: var(--panel-shadow); }
  .optics-strand { margin-top: 24px; box-shadow: 6px 6px 0 rgba(18,47,57,.05); }
  .strand-module-grid button { min-width: 0; }
  .open-experience > * + * { scroll-margin-top: 24px; }
  :is(.ray-law-lab,.color-mix-lab,.celestial-lab,.plane-mirror-lab,.curved-mirror-lab,.invisible-light-lab,.experience-canvas,.lens-system-3d-lab) { max-width: 100%; }

  /* Precision lens workbench */
  .workbench-header { min-width: 0; }
  .workbench-brand, .workbench-actions { min-width: 0; }
  .workbench-layout { width: 100%; }
  .experiment-stage, .lens-inspector, .data-dock { min-width: 0; }
  .stage-heading > * { min-width: 0; }
  .stage-heading p { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .lens-inspector { scrollbar-color: #8aa19e transparent; scrollbar-width: thin; }
  .instrument-control { padding-block: 16px; }
  .dock-table { scrollbar-width: thin; }

  /* Intro and Harness should never cover more content than necessary. */
  .page-intro-content { min-width: 0; }
  .page-intro-content > p { max-width: 620px; }
  .harness-panel { max-height: calc(100dvh - 112px); }
  .harness-dialogue-body { min-height: 0; }
  .harness-chat-stream { scrollbar-width: thin; scrollbar-color: #7da79f transparent; }
  .harness-composer textarea { max-height: 170px; }

  @media (max-width: 1180px) {
    :root { --page-gutter: 28px; }
    .hero-lab { grid-template-columns: 1fr; gap: 0; }
    .hero-copy { padding: 68px 0 38px; }
    .hero-instrument { width: 100%; min-height: 570px; margin: 20px 0 68px; }
    .discovery-home-hero { width: calc(100% - 44px); max-width: none; }
    .discovery-field-section, .discovery-tool-note { width: calc(100% - 44px); max-width: none; }
    .science-structure-v2 .science-layout { grid-template-columns: 190px minmax(0,1fr); }
  }

  @media (max-width: 900px) {
    :root { --page-gutter: 22px; }
    .home-nav nav a { display: none; }
