@layer base {
  :root {
    color-scheme: light;
    --ink: #102930;
    --ink-deep: #071c24;
    --ink-mid: #12333c;
    --paper: #f1eee5;
    --paper-bright: #fbf9f2;
    --paper-dark: #ded9cc;
    --cyan: #29d8bb;
    --cyan-bright: #66f2d5;
    --amber: #e3b954;
    --coral: #eb795f;
    --blue: #5bb4e6;
    --muted: #71858a;
    --line: rgba(16, 41, 48, 0.16);
    --kai: "Kaiti SC", "STKaiti", "KaiTi", "楷体", serif;
    --serif: var(--kai);
    --sans: var(--kai);
    --mono: var(--kai);
  }

  body {
    color: var(--ink);
    background: var(--paper);
    font-family: var(--sans);
    font-size: 16px;
    font-weight: 600;
    line-height: 1.6;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  body *, body *::before, body *::after { font-family: var(--kai) !important; }
  body :is(p, li, span, small, label, input, textarea, select, option, output, dt, dd, th, td, a) { font-weight: 600 !important; }
  body :is(h1, h2, h3, strong, b, button, th) { font-weight: 700 !important; }

  ::selection { color: var(--ink-deep); background: var(--cyan-bright); }
  button, a { transition: color .18s ease, background .18s ease, border-color .18s ease, transform .18s ease, opacity .18s ease; }
  button:focus-visible, a:focus-visible, input:focus-visible, [role="button"]:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }
}

@layer components {
  .app-recovery-screen { min-height: 100vh; display: grid; place-items: center; padding: 30px; color: #e6f2ef; background: linear-gradient(rgba(102,242,213,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(102,242,213,.035) 1px,transparent 1px),#071c24; background-size: 30px 30px; }
