  .route-loading span { width: 48px; height: 48px; border: 1px solid #31515a; border-top-color: var(--cyan-bright); border-radius: 50%; animation: spin .8s linear infinite; }
  .route-loading strong { margin-top: 8px; font-family: var(--serif); font-size: 18px; letter-spacing: .06em; }
