  .field-motif-grid line { stroke: currentColor; stroke-width: .7; opacity: .14; }
  .field-axis, .field-measure, .field-tick { fill: none; stroke: currentColor; stroke-width: 1.2; stroke-dasharray: 6 4; opacity: .72; }
  .field-glass { fill: color-mix(in srgb,currentColor 16%,transparent); stroke: currentColor; stroke-width: 2.2; }
  .field-energy, .field-force, .field-wave, .field-wire, .field-device, .field-beam, .field-battery, .field-resistor, .field-switch, .field-beaker, .field-thermometer, .field-curve, .field-balance, .field-pan, .field-cylinder { fill: none; stroke: currentColor; stroke-width: 2.7; stroke-linecap: round; stroke-linejoin: round; }
  .field-energy.warm, .field-force.warm { stroke: #efbd59; filter: drop-shadow(0 0 3px rgba(239,189,89,.55)); }
  .field-energy.cool, .field-force.cool { stroke: #5bd9c7; filter: drop-shadow(0 0 3px rgba(91,217,199,.55)); }
  .field-point, .field-charge { fill: currentColor; }
  .field-charge { transform-box: fill-box; transform-origin: center; }
  .field-wave.wave-a { stroke-width: 3; filter: drop-shadow(0 0 3px currentColor); animation: field-wave-drift 4s linear infinite; }
  .field-wave.wave-b { stroke-width: 1.5; opacity: .55; stroke-dasharray: 5 5; animation: field-wave-drift 6s linear infinite reverse; }
  .field-fulcrum { fill: color-mix(in srgb,currentColor 18%,transparent); stroke: currentColor; stroke-width: 2; }
  .field-wire { stroke-width: 3.2; }
  .field-battery { stroke-width: 4; }
  .field-charge { filter: drop-shadow(0 0 4px currentColor); animation: field-charge-pulse 1.5s ease-in-out infinite; }
  .field-water { fill: color-mix(in srgb,currentColor 24%,transparent); stroke: currentColor; stroke-width: 1.2; }
  .field-mercury { fill: none; stroke: #ef765b; stroke-width: 7; stroke-linecap: round; }
  .field-curve { stroke: #ef765b; filter: drop-shadow(0 0 3px rgba(239,118,91,.55)); }
  .field-sample { fill: color-mix(in srgb,currentColor 55%,transparent); stroke: currentColor; stroke-width: 1.5; }
  .mixed-orbit { fill: none; stroke: currentColor; stroke-width: 1.1; stroke-dasharray: 7 6; opacity: .55; transform-origin: 180px 88px; animation: mixed-field-orbit 24s linear infinite; }
  .mixed-orbit.orbit-two { animation-direction: reverse; animation-duration: 18s; }
  .mixed-core { fill: #173847; stroke: currentColor; stroke-width: 2; }
  .mixed-nodes circle { fill: #f5f0e6; stroke: currentColor; stroke-width: 1.5; }
