  .sound-sim, .lever-sim, .circuit-sim, .thermal-sim, .density-sim { position: relative; min-height: 450px; overflow: hidden; color: white; background: #0a2632; }
  .sound-sim::before, .lever-sim::before, .circuit-sim::before, .thermal-sim::before, .density-sim::before { content: ""; position: absolute; inset: 0; background-image: linear-gradient(rgba(104,185,232,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(104,185,232,.06) 1px,transparent 1px); background-size: 30px 30px; }
  .sound-sim::after, .lever-sim::after, .circuit-sim::after, .thermal-sim::after, .density-sim::after, .concept-sim::after { position: absolute; z-index: 3; top: 18px; right: 19px; min-height: 31px; display: flex; align-items: center; padding: 0 10px; color: var(--science-accent); border: 1px solid color-mix(in srgb,var(--science-accent) 52%,transparent); background: rgba(5,25,32,.74); font-size: 10px; font-weight: 700; letter-spacing: .1em; backdrop-filter: blur(7px); }
  .sound-sim::after { content: "TIME TRACE  /  T = 1/f"; }
  .lever-sim::after { content: "MOMENT  /  F₁l₁ = F₂l₂"; }
  .circuit-sim::after { content: "CIRCUIT  /  I = U ÷ R"; }
  .thermal-sim::after { content: "THERMAL  /  ηPt = cmΔT"; }
  .density-sim::after { content: "DENSITY  /  ρ = m ÷ (V₂−V₁)"; }
  .sound-sim svg { position: absolute; z-index: 2; left: 16%; right: 4%; top: 22%; width: 80%; height: 240px; overflow: visible; }
  .sound-sim polyline { fill: none; stroke: var(--science-accent); stroke-width: 2.5; filter: drop-shadow(0 0 5px var(--science-accent)); }
  .speaker { position: absolute; z-index: 4; left: 5%; top: 31%; width: 95px; height: 150px; border: 7px solid #8aa0a6; border-radius: 12px; background: #173c49; }
  .speaker i { position: absolute; left: 13px; top: 35px; width: 55px; height: 55px; border: 6px solid #506f79; border-radius: 50%; background: #071c24; }
  .speaker.playing i { animation: speaker-vibrate .13s ease-in-out infinite alternate; }
  .speaker b { position: absolute; left: 31px; bottom: 13px; width: 20px; height: 20px; border: 3px solid #506f79; border-radius: 50%; }
  .sound-particles i { position: absolute; z-index: 4; left: 17%; top: 49%; width: 6px; height: 6px; border-radius: 50%; background: #eaffff; box-shadow: 0 0 9px var(--science-accent); animation: sound-particle 1.6s linear infinite; }
  .sound-readout, .balance-status, .circuit-meter, .density-result { position: absolute; z-index: 5; right: 25px; bottom: 23px; display: grid; gap: 4px; padding: 12px 15px; border: 1px solid var(--science-accent); background: rgba(8,29,37,.85); }
  .sound-readout span, .balance-status span, .circuit-meter span, .density-result small { color: #819da2; font-size: 7px; }
  .sound-readout strong, .balance-status strong, .circuit-meter strong, .density-result strong { font-family: var(--serif); font-size: 15px; }
  .sound-readout small { color: var(--science-accent); font: 10px var(--mono); }

  .lever-scale { position: absolute; left: 10%; right: 10%; top: 20%; display: flex; justify-content: space-between; }
