  .weight { position: absolute; top: 18px; width: var(--weight); height: var(--weight); display: grid; place-items: center; color: #16313e; border-radius: 7px; background: var(--science-accent); transform: translateX(-50%); font: 8px var(--mono); }
  .weight::before { content: ""; position: absolute; left: 50%; bottom: 100%; width: 1px; height: 35px; background: #cbd8d6; }
