  .balance-status.balanced { color: #67e1c9; }

  .circuit-wiring-bench { min-height: 640px; background: radial-gradient(circle at 48% 38%,rgba(239,118,91,.075),transparent 31%),linear-gradient(145deg,#061a22,#0c2b35 65%,#071b23); isolation: isolate; }
  .circuit-wiring-bench::before { opacity: .48; background-image: linear-gradient(rgba(239,118,91,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(239,118,91,.035) 1px,transparent 1px); background-size: 24px 24px; }
  .circuit-wiring-bench::after { content: "LIVE WIRING  /  请先接线再通电"; }
