  .circuit-bench-toolbar > span { min-height: 33px; display: flex; align-items: center; gap: 8px; padding: 0 11px; color: #92aeb2; border: 1px solid #35545d; background: rgba(4,20,27,.82); backdrop-filter: blur(8px); }
