  .circuit-bench-toolbar button:hover:not(:disabled) { color: white; border-color: var(--science-accent); }
  .circuit-bench-toolbar button:disabled { opacity: .35; cursor: not-allowed; }
  .bench-short-wire path { fill: none; stroke: #e95644; stroke-width: 9; stroke-linecap: round; filter: drop-shadow(0 0 7px rgba(233,86,68,.65)); }
  .bench-short-wire text { fill: #ff9c87; font: 800 11px var(--mono); writing-mode: vertical-rl; }
