  .circuit-board-surface { stroke: #2c4952; stroke-width: 2; filter: drop-shadow(0 14px 22px rgba(0,0,0,.24)); }
  .bench-wire-guide { fill: none; stroke: #3f5c64; stroke-width: 5; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 7 11; opacity: .5; }
  .bench-wire-shadow, .bench-wire, .bench-current { fill: none; stroke-linecap: round; stroke-linejoin: round; }
