  .bench-wire-group.active .bench-current { stroke: #ffe8aa; animation: bench-current-flow var(--current-speed) linear infinite; filter: drop-shadow(0 0 4px #fff0af); }
  .bench-battery rect:first-child { fill: #202f34; stroke: #9d7d56; stroke-width: 2; }
  .bench-battery rect:nth-child(2) { fill: #101d21; stroke: #4e6265; }
  .bench-battery text { fill: #9dafb1; text-anchor: middle; font-size: 12px; }
