  .bench-battery .polarity { font-size: 24px; font-weight: 900; }
  .bench-battery .plus { fill: #ff755e; } .bench-battery .minus { fill: #6bc6d6; }
  .bench-switch { cursor: pointer; }
  .bench-switch rect { fill: #172d35; stroke: #526c72; stroke-width: 2; }
  .bench-switch line { stroke: #f0c96f; stroke-width: 8; stroke-linecap: round; transform-origin: 257px 125px; transition: x2 .2s ease,y2 .2s ease; }
