  .instrument-photon { position: absolute; z-index: 6; left: 3%; top: 48%; width: 7px; height: 7px; border-radius: 50%; background: #eafff9; box-shadow: 0 0 10px #5ee0c8; animation: instrument-light 2s linear infinite; }
