  .instrument-view { position: absolute; z-index: 3; right: 7%; top: 27%; width: 155px; height: 155px; display: grid; place-items: center; overflow: hidden; border: 8px solid #ccb68f; border-radius: 50%; background: #183a47; }
  .instrument-view > svg { width: 64px; height: 64px; color: #e5d39e; stroke-width: 1.55; transition: transform .2s ease, filter .2s ease; }
