  @keyframes orbit-turn { to { transform: rotate(360deg); } }
  @keyframes beam-flow { to { background-position: 36px 0; } }
  @keyframes pulse-travel { 0% { left: 18%; opacity: 0; transform: translateY(-18px); } 15% { opacity: 1; } 55% { transform: translate(250px,18px); } 100% { left: 72%; opacity: 0; transform: translate(430px,-12px); } }
