  .window-view i::before { content: ""; position: absolute; left: -27px; top: -31px; border-left: 31px solid transparent; border-right: 31px solid transparent; border-bottom: 52px solid #3f704d; }
  .mini-lens { position: absolute; left: 46%; top: 43%; color: #6fdaed; font: 42px var(--serif); }
  .white-card { position: absolute; right: 10%; top: 25%; width: 190px; height: 185px; border: 8px solid #bfb8a9; background: #eee9de; box-shadow: 13px 13px 0 rgba(0,0,0,.18); }
  .white-card i { position: absolute; left: 50%; top: 62px; width: 6px; height: 54px; background: #596248; transform: rotate(180deg); }
  .white-card i::after { content: ""; position: absolute; left: -24px; bottom: 35px; border-left: 27px solid transparent; border-right: 27px solid transparent; border-bottom: 47px solid #5d8260; }
  .white-card span { position: absolute; right: 0; bottom: 10px; left: 0; text-align: center; color: #77817e; font-size: 8px; }
  .discovery-strip, .prediction-saved, .law-feedback, .extension-strip { display: flex; align-items: center; gap: 12px; margin: 20px 28px; padding: 15px 17px; border: 1px solid #dfc178; background: #fff1c8; }
  .discovery-strip svg, .prediction-saved svg { flex: 0 0 auto; color: #d38b23; }
  .discovery-strip p, .prediction-saved p { color: #716a58; font-size: 9px; line-height: 1.7; }
  .discovery-strip strong { color: #203440; }
  .lesson-next { min-height: 74px; display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 15px 28px; border-top: 1px solid #d5d0c5; }
  .lesson-next > span { color: #828b8d; font-size: 9px; }
  .lesson-next button, .back-link { min-height: 40px; display: inline-flex; align-items: center; justify-content: center; gap: 9px; padding: 0 16px; color: white; background: #203d4d; cursor: pointer; font-size: 10px; font-weight: 700; }
  .lesson-next button.secondary, .back-link { color: #203440; border: 1px solid #203440; background: transparent; }
  .lesson-next button:disabled { opacity: .35; cursor: not-allowed; }

  .prediction-question { padding: 30px 40px; }
  .prediction-question > span { color: #df6c50; font: 8px var(--mono); letter-spacing: .12em; }
  .prediction-question h2 { max-width: 720px; margin: 10px 0 22px; font-family: var(--serif); font-size: 21px; line-height: 1.5; }
  .prediction-question > div { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
  .prediction-question button { min-height: 58px; display: grid; grid-template-columns: 31px 1fr 18px; align-items: center; gap: 11px; padding: 8px 13px; text-align: left; color: #536568; border: 1px solid #cbc6bb; background: #f4f0e7; cursor: pointer; font-size: 11px; }
  .prediction-question button i { width: 29px; height: 29px; display: grid; place-items: center; border: 1px solid #aeb1ac; border-radius: 50%; font: normal 9px var(--mono); }
  .prediction-question button.selected { color: #173645; border-color: #4fae9e; background: #e7f4ee; }
  .prediction-question button.selected i { color: white; border-color: #4fae9e; background: #4fae9e; }
  .prediction-saved strong { font-family: var(--serif); font-size: 11px; }
  .prediction-saved p { margin-top: 4px; }

  .experiment-mission-bar { min-height: 112px; display: flex; align-items: center; justify-content: space-between; gap: 25px; padding: 20px 25px; color: white; background: #183746; }
  .experiment-mission-bar span { color: #63ddc7; font: 8px var(--mono); letter-spacing: .12em; }
  .experiment-mission-bar h1 { margin-top: 5px; font-family: var(--serif); font-size: 24px; }
  .experiment-mission-bar p { margin-top: 5px; color: #93aeb3; font-size: 9px; }
  .mission-actions { display: flex; gap: 7px; }
  .mission-actions button { min-height: 35px; display: flex; align-items: center; gap: 6px; padding: 0 10px; color: #c5d5d5; border: 1px solid #41616a; background: #224653; cursor: pointer; font-size: 8px; }
  .mission-hint { padding: 10px 18px; color: #725f38; border-bottom: 1px solid #dcbf7e; background: #fff0c9; font-size: 9px; line-height: 1.6; }
  .student-canvas { height: min(53vh, 510px); min-height: 430px; background: #071c24; }
  .experiment-reading { display: grid; grid-template-columns: .8fr .8fr 1.4fr 1fr; color: white; border-top: 1px solid #2c4a54; background: #102c39; }
  .experiment-reading div { min-height: 61px; padding: 11px 14px; border-right: 1px solid #2c4a54; }
  .experiment-reading div:last-child { border-right: 0; }
  .experiment-reading span { display: block; color: #6f8b90; font-size: 7px; }
  .experiment-reading strong { display: block; margin-top: 7px; font: 9px var(--mono); }
  .experiment-reading .success { color: #64dfc9; background: #163f42; }
  .mission-progress { display: grid; grid-template-columns: repeat(4, 1fr); background: #e7e2d7; }
  .mission-progress button { min-height: 60px; display: flex; align-items: center; gap: 8px; padding: 0 13px; color: #7e8889; border-right: 1px solid #c5c0b6; background: transparent; cursor: pointer; font-size: 9px; }
  .mission-progress button:disabled { opacity: .4; cursor: not-allowed; }
  .mission-progress button.active { color: #203440; background: #fbf8ef; box-shadow: inset 0 3px #df6c50; }
  .mission-progress button.done { color: #2a7a6d; }
  .mission-progress i { width: 23px; height: 23px; display: grid; place-items: center; border: 1px solid currentColor; border-radius: 50%; font-style: normal; font-size: 8px; }

  .law-table { margin: 25px 35px; border-top: 1px solid #bbb8af; border-left: 1px solid #bbb8af; }
  .law-row { min-height: 60px; display: grid; grid-template-columns: 160px 1fr 75px; align-items: center; }
  .law-row > * { height: 100%; display: flex; align-items: center; padding: 0 15px; border-right: 1px solid #bbb8af; border-bottom: 1px solid #bbb8af; }
  .law-head { min-height: 38px; color: #757f80; background: #e8e3d9; font-size: 8px; }
  .law-row strong { font: 14px var(--mono); }
  .law-row select { width: 100%; color: #30444c; border: 0; border-right: 1px solid #bbb8af; border-bottom: 1px solid #bbb8af; background: #f7f4ec; font-size: 10px; }
  .law-row i { justify-content: center; color: #929896; font-style: normal; font-size: 8px; }
  .law-row i.correct { color: #2c8e7c; background: #e1f1ea; }
  .law-row i.wrong { color: #c55742; background: #f9e4dc; }
  .law-feedback { color: #a3513f; border-color: #df9e8c; background: #fde4dc; }
  .law-feedback.success { color: #2f756a; border-color: #86c5b7; background: #e1f3ed; }
  .law-feedback strong { font-family: var(--serif); font-size: 11px; }
  .law-feedback p { margin-top: 4px; font-size: 9px; }

  .application-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 27px 32px; }
  .application-grid article { padding: 18px; border: 1px solid #c9c4b9; background: #f3efe6; }
  .application-grid article > div { display: flex; align-items: center; gap: 10px; color: #1e4050; }
  .application-grid article > div span { font-family: var(--serif); font-size: 15px; }
  .application-grid article > p { min-height: 39px; margin: 17px 0 10px; color: #657376; font-size: 9px; line-height: 1.6; }
  .application-grid button { width: 100%; min-height: 37px; display: flex; align-items: center; justify-content: space-between; margin-top: 6px; padding: 0 10px; color: #677476; border: 1px solid #cbc7be; background: #faf8f1; cursor: pointer; font-size: 9px; }
  .application-grid button.selected { color: #1f574f; border-color: #5db4a4; background: #e0f2ec; }
  .extension-strip { justify-content: space-between; color: #755d30; }
  .extension-strip div { flex: 1; }
  .extension-strip strong { font-family: var(--serif); font-size: 11px; }
  .extension-strip p { margin-top: 3px; font-size: 8px; }
  .lesson-complete { display: flex; align-items: center; gap: 18px; margin: 24px 32px; padding: 24px; color: white; background: #183b47; box-shadow: 6px 6px 0 #64dfc9; }
  .lesson-complete > svg { color: #64dfc9; }
  .lesson-complete span { color: #64dfc9; font: 7px var(--mono); letter-spacing: .14em; }
  .lesson-complete h2 { margin-top: 5px; font-family: var(--serif); font-size: 19px; }
  .lesson-complete p { margin-top: 5px; color: #9cb4b7; font-size: 8px; }

  .learning-notebook { border-left: 1px solid #cbc6bb; background-color: #f8f5ed; background-image: linear-gradient(#dfdbd1 1px, transparent 1px); background-size: 100% 28px; }
  .notebook-head { height: 75px; display: flex; align-items: center; gap: 10px; padding: 15px 18px; border-bottom: 1px solid #c9c4b9; background: #eee9df; }
  .notebook-head svg { color: #df6c50; }
  .learning-notebook section { min-height: 105px; padding: 18px; border-bottom: 1px solid #d6d1c7; }
  .learning-notebook section > span { color: #df6c50; font: 7px var(--mono); letter-spacing: .12em; }
  .learning-notebook section > p { margin-top: 12px; color: #677578; font-family: var(--serif); font-size: 11px; line-height: 1.7; }
  .notebook-dots { display: flex; gap: 7px; margin-top: 12px; }
  .notebook-dots i { width: 24px; height: 24px; display: grid; place-items: center; border: 1px solid #bbb8b0; border-radius: 50%; }
  .notebook-dots i.done { color: white; border-color: #56a996; background: #56a996; }
  .learning-notebook .notebook-status { min-height: 70px; display: flex; align-items: flex-start; gap: 9px; color: #559586; background: rgba(223,240,232,.6); }
  .notebook-status p { margin-top: 0 !important; font-size: 9px !important; }
  .student-loading { background: #183746; }

  /* Workbench */
  .workbench-page { min-height: 100vh; color: #e4ecea; background: #06171d; }
  .workbench-header { height: 68px; display: flex; align-items: center; justify-content: space-between; padding: 0 18px; border-bottom: 1px solid #244049; background: #0b252d; }
  .workbench-brand { display: flex; align-items: center; gap: 14px; }
  .workbench-brand > span { width: 1px; height: 28px; background: #35515a; }
  .workbench-brand > div { display: grid; gap: 3px; }
  .workbench-brand small { color: #6c8b91; font: 8px var(--mono); letter-spacing: .12em; }
  .workbench-brand strong { font-family: var(--serif); font-size: 16px; letter-spacing: .04em; }
  .workbench-actions { display: flex; align-items: center; gap: 4px; }
  .workbench-actions > i { width: 1px; height: 25px; margin: 0 8px; background: #35515a; }
  .workbench-actions button, .exit-button { min-height: 36px; display: inline-flex; align-items: center; gap: 7px; padding: 0 11px; color: #a9bcbc; background: transparent; cursor: pointer; font-size: 11px; }
  .workbench-actions button:hover, .exit-button:hover { color: white; background: #173740; }
  .workbench-actions button:disabled { opacity: .3; cursor: not-allowed; }
  .workbench-actions .saved { color: var(--cyan-bright); }
  .workbench-fullscreen-button > span { display: grid; gap: 1px; text-align: left; }
  .workbench-fullscreen-button strong { font-size: 12px; }
  .workbench-fullscreen-button small { color: #628086; font-size: 9px; }
  .exit-button { margin-left: 5px; border: 1px solid #38535a; }

  .workbench-layout { height: calc(100vh - 248px); min-height: 550px; display: grid; grid-template-columns: 116px minmax(520px, 1fr) 326px; }
  .component-rail { padding: 17px 12px; border-right: 1px solid #244049; background: #0b2229; }
  .rail-title { display: flex; justify-content: space-between; align-items: center; margin-bottom: 13px; padding: 0 3px; }
  .rail-title span { font-size: 12px; font-weight: 650; }
  .rail-title small { color: #58747a; font: 7px var(--mono); }
  .rail-item { width: 100%; min-height: 92px; margin-bottom: 9px; display: grid; place-items: center; align-content: center; gap: 4px; color: #718a8e; border: 1px solid #26434a; background: #0d2931; cursor: default; }
  .rail-item.active { color: #dce8e6; border-color: #3d6268; }
  .rail-item b { font-family: var(--serif); font-size: 13px; }
  .rail-item small { color: #577178; font-size: 8px; }
  .candle-glyph, .lens-glyph { color: var(--cyan-bright); font: 22px var(--mono); }
  .screen-glyph { width: 9px; height: 30px; border: 1px solid #a9bdbb; background: rgba(255,255,255,.06); }
  .rail-note { display: flex; gap: 7px; align-items: flex-start; margin-top: 20px; padding: 12px 5px; color: #567278; border-top: 1px solid #27434a; font-size: 8px; line-height: 1.6; }
  .rail-note svg { flex: 0 0 auto; color: var(--cyan); }

  .experiment-stage { position: relative; min-width: 0; display: grid; grid-template-rows: 43px 1fr; background: var(--ink-deep); }
  .workbench-cue { top: 66px; --science-accent: var(--cyan); }
  .stage-heading { display: grid; grid-template-columns: 1fr auto auto; gap: 25px; align-items: center; padding: 0 17px; border-bottom: 1px solid #244049; color: #adc0c0; background: #0b252d; }
  .stage-heading > div { display: flex; align-items: center; gap: 9px; font-size: 10px; font-weight: 700; letter-spacing: .05em; }
  .stage-heading p { color: #5f7d82; font-size: 9px; }
  .stage-heading button { display: inline-flex; align-items: center; gap: 8px; padding: 6px 10px; color: var(--cyan-bright); border: 1px solid #2a5b5a; background: #103437; cursor: pointer; font-size: 9px; }
  .stage-heading button:disabled { opacity: .3; cursor: not-allowed; }
  .lens-canvas-host { position: relative; min-width: 0; min-height: 0; overflow: hidden; }
  .lens-canvas-host canvas { display: block; }
  .canvas-scale-note { position: absolute; left: 14px; bottom: 12px; padding: 6px 9px; color: #59787d; border: 1px solid #1e3c44; background: rgba(5,22,28,.8); font: 8px var(--mono); letter-spacing: .08em; pointer-events: none; }
  .canvas-motion-toggle { position: absolute; right: 14px; bottom: 12px; min-height: 29px; display: flex; align-items: center; gap: 6px; padding: 0 9px; color: #71d8c5; border: 1px solid #275159; background: rgba(5,22,28,.86); cursor: pointer; font-size: 8px; }
  .canvas-motion-toggle:hover { color: #d8fff7; border-color: #55b6a8; }

  .lens-inspector { overflow-y: auto; border-left: 1px solid #244049; color: var(--ink); background: #eae6da; }
  .inspector-heading { min-height: 67px; display: flex; align-items: center; justify-content: space-between; padding: 14px 17px; border-bottom: 1px solid #c9c4b8; }
  .inspector-heading span { color: #7e8986; font: 7px var(--mono); letter-spacing: .15em; }
  .inspector-heading h2 { margin-top: 3px; font-family: var(--serif); font-size: 18px; }
  .inspector-heading svg { color: #7d8e8c; }
  .inspector-section { padding: 7px 17px; border-bottom: 1px solid #c9c4b8; }
  .instrument-control { display: block; padding: 11px 0; border-bottom: 1px dashed rgba(16,41,48,.13); }
  .instrument-control:last-child { border-bottom: 0; }
  .instrument-control > span { display: flex; align-items: center; justify-content: space-between; margin-bottom: 9px; }
  .instrument-control b { font-family: var(--serif); font-size: 12px; }
  .instrument-control i { color: #7c8987; font: italic 11px var(--serif); }
  .range-line { display: grid; grid-template-columns: 1fr 77px; gap: 10px; align-items: center; }
  .range-line input { width: 100%; height: 3px; margin: 0; appearance: none; background: linear-gradient(90deg, var(--ink-deep) var(--progress), #c2beb3 var(--progress)); }
  .range-line input::-webkit-slider-thumb { width: 13px; height: 13px; appearance: none; border: 2px solid var(--paper-bright); border-radius: 50%; background: var(--ink-deep); box-shadow: 0 0 0 1px var(--ink-deep); cursor: ew-resize; }
  .range-line output { padding: 6px 5px; text-align: right; color: var(--cyan-bright); background: var(--ink-deep); font: 11px var(--mono); }
  .range-line output small { color: #789096; font-size: 7px; }
  .display-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; padding-top: 12px; padding-bottom: 12px; }
  .display-options button { min-height: 39px; display: flex; align-items: center; justify-content: center; gap: 5px; color: #6d7b79; border: 1px solid #c0bcb1; background: transparent; cursor: pointer; font-size: 9px; }
  .display-options button.selected { color: var(--ink-deep); border-color: var(--ink-deep); background: #d8d5cb; }
  .result-console { margin: 14px; padding: 14px; color: #dbe7e5; background: var(--ink-deep); box-shadow: 5px 5px 0 #cbc6b9; }
  .result-console.result-standby { color: #91a3a3; background: #17333a; box-shadow: 5px 5px 0 #b9b6ae; }
  .result-console.result-standby .result-equation { color: #6c8d8c; }
  .result-console.result-standby dd { color: #8ca0a0; }
  .console-head { display: flex; justify-content: space-between; align-items: center; color: #6f8b90; font: 8px var(--mono); letter-spacing: .14em; }
  .console-head i { padding: 3px 5px; color: var(--coral); border: 1px solid currentColor; font-style: normal; }
  .console-head i.virtual { color: var(--cyan); }
  .result-equation { margin: 13px 0; color: var(--cyan-bright); font: 15px var(--mono); }
  .result-console dl { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid #244149; border-left: 1px solid #244149; }
  .result-console dl div { min-height: 51px; padding: 8px; border-right: 1px solid #244149; border-bottom: 1px solid #244149; }
  .result-console dt { color: #6d8a90; font-size: 8px; }
  .result-console dd { margin-top: 5px; font: 10px var(--mono); }
  .result-console p { min-height: 44px; margin-top: 11px; color: #a7bab9; font-size: 9px; line-height: 1.65; }
  .focus-meter { margin-top: 11px; color: #81989a; font-size: 8px; }
  .focus-meter.focused { color: var(--cyan-bright); }
  .focus-meter i { display: block; height: 3px; margin-top: 7px; background: #19343b; }
  .focus-meter b { display: block; height: 100%; background: currentColor; transition: width .25s ease; }

  .data-dock { height: 180px; display: grid; grid-template-columns: 180px minmax(0, 1fr) 180px; border-top: 1px solid #244049; color: var(--ink); background: #e2ded3; }
  .dock-summary { display: flex; flex-direction: column; justify-content: center; padding: 20px; border-right: 1px solid #c3beb3; }
  .dock-summary span { color: #7e8986; font: 7px var(--mono); letter-spacing: .13em; }
  .dock-summary strong { margin-top: 5px; font: 700 41px var(--serif); }
  .dock-summary small { color: #71807e; font-size: 9px; }
  .dock-table { min-width: 0; overflow: auto; }
  .dock-table table { width: 100%; border-collapse: collapse; font-size: 9px; }
  .dock-table th, .dock-table td { height: 31px; padding: 0 12px; text-align: left; border-right: 1px solid #cbc6bb; border-bottom: 1px solid #cbc6bb; white-space: nowrap; }
  .dock-table th { color: #6f7e7c; background: #d8d4ca; font-weight: 600; }
  .empty-log { height: 100%; display: grid; place-items: center; color: #899390; font-size: 10px; }
  .dock-actions { display: flex; flex-direction: column; justify-content: center; gap: 8px; padding: 18px; border-left: 1px solid #c3beb3; }
  .dock-actions button { min-height: 37px; display: flex; align-items: center; justify-content: center; gap: 7px; color: var(--ink); border: 1px solid var(--ink); background: transparent; cursor: pointer; font-size: 9px; }
  .dock-actions button:disabled { opacity: .35; cursor: not-allowed; }
  .dock-actions .button-record { color: white; background: var(--ink-deep); box-shadow: 3px 3px 0 var(--cyan); }

  /* Project-wide Kaiti typography: bold, readable and visually direct */
  p { font-size: 15px !important; line-height: 1.75 !important; }
  small { font-size: 12px !important; line-height: 1.45 !important; }
  button, input, textarea, select, option, output, label { font-size: 14px !important; }
  nav a, header > a { font-size: 14px !important; }
  table, th, td, dt, dd { font-size: 14px !important; }
  svg text { font-size: 12px !important; font-weight: 700 !important; }

  .brand-words strong { font-size: 21px; }
  .brand-words small, .route-loading small { font-size: 12px; }
  .route-loading strong { font-size: 22px; }

  .page-intro-trigger { min-height: 44px; font-size: 14px; }
  .page-intro-visual > small, .optics-art-title span { font-size: 11px; }
  .optics-art-title strong { font-size: 16px; }
  .page-intro-eyebrow { font-size: 13px; }
  .page-intro-content h2 { font-size: clamp(30px,3.3vw,42px); }
  .page-intro-content p, .page-intro-content li { font-size: 15px; line-height: 1.75; }
  .page-intro-content li b { font-size: 12px; }

  .harness-dock-trigger { min-height: 56px; }
  .harness-dock-trigger small { font-size: 11px; }
  .harness-dock-trigger strong { font-size: 16px; }
  .harness-dock-trigger > b { font-size: 12px; }
  .harness-panel > header span, .harness-section-title > small, .harness-panel > footer > span { font-size: 11px; }
  .harness-panel > header strong { font-size: 20px; }
  .harness-section-title > span { font-size: 16px; }
  .harness-metrics strong { font-size: 22px; }
  .harness-insights > button > b, .harness-trace time { font-size: 11px; }
  .harness-capture textarea { font-size: 14px; }

  .home-nav nav, .explore-header nav, .student-header nav { font-size: 14px; }
  .version-chip { font-size: 13px; }
  .eyebrow { font-size: 14px; }
  .hero-description { font-size: 18px !important; }
  .hero-stats dt { font-size: 26px; }
  .hero-stats dd { font-size: 14px; }
  .hero-instrument::before, .optic-axis::before, .optic-axis::after { font-size: 12px; }
  .formula-plate span, .formula-plate small { font-size: 12px; }
  .formula-plate strong { font-size: 24px; }
  .section-heading span, .architecture-title span { font-size: 13px; }
  .lab-number { font-size: 18px; }
  .lab-card h3 { font-size: 27px; }
  .lab-status { font-size: 12px; }
  .architecture-steps b { font-size: 15px; }
  .architecture-steps strong { font-size: 23px; }
