  .noise-control-console > div { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); }
  .noise-control-console > div > section { padding: 14px; border-right: 1px solid #d1dad8; }
  .noise-control-console > div > section:last-child { border-right: 0; }
  .noise-control-console section > header { display: flex; align-items: center; gap: 9px; margin-bottom: 10px; }
  .noise-control-console section > header > b { color: #d46c55; font: 800 20px var(--mono); }
  .noise-control-console section > header span { display: grid; }
  .noise-control-console section > header small { color: #829398; font: 800 7px var(--mono); letter-spacing: .12em; }
  .noise-control-console section > header strong { color: #244b55; font-size: 11px; }
  .noise-control-console section > button { width: 100%; min-height: 64px; display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 7px; padding: 10px; text-align: left; color: #60777c; border: 1px solid #cbd4d2; background: rgba(255,255,255,.4); transition: .2s ease; }
  .noise-control-console section > button:hover { border-color: #69bdcd; }
  .noise-control-console section > button.active { color: #244d57; border-color: #43b9cf; background: #f7faf7; box-shadow: inset 3px 0 #4dc7dc; }
  .noise-control-console section > button span { display: grid; gap: 3px; }
  .noise-control-console section > button span b { font-size: 10px; }
  .noise-control-console section > button span small { font-size: 8px; }
  .noise-control-console section > button em { flex: 0 0 auto; color: #d36f58; font: 700 8px var(--mono); font-style: normal; }

  .auditorium-stage { min-height: 390px; display: grid; grid-template-columns: 1fr 220px; grid-template-rows: 41px 1fr; }
  .auditorium-stage > header { grid-column: 1/-1; }
  .auditorium-stage > header span { display: flex; align-items: center; gap: 8px; color: #68d4e8; }
  .auditorium-room { position: relative; min-height: 345px; overflow: hidden; border-right: 1px solid rgba(92,200,222,.18); perspective: 500px; }
  .auditorium-room::before { content: ""; position: absolute; inset: 18px 20px 36px; border: 1px solid rgba(99,202,222,.25); transform: perspective(500px) rotateX(2deg); background: linear-gradient(90deg,rgba(92,211,231,.04),transparent 45%); }
  .auditorium-curtain { position: absolute; left: 40px; top: 45px; bottom: 45px; width: 40px; border-left: 4px double #b56859; border-right: 4px double #b56859; background: repeating-linear-gradient(90deg,rgba(185,99,80,.35) 0 5px,rgba(98,34,33,.22) 5px 10px); }
  .auditorium-speaker { position: absolute; left: 100px; top: 50%; translate: 0 -50%; width: 50px; height: 70px; display: grid; place-items: center; color: #85dfef; border: 1px solid rgba(133,223,239,.35); background: #092a37; }
  .auditorium-speaker i { position: absolute; width: 6px; height: 6px; border-radius: 50%; background: #6ee1bc; box-shadow: 0 0 12px #6ee1bc; }
  .auditorium-echoes { position: absolute; left: 122px; right: 60px; top: 50%; height: 160px; translate: 0 -50%; overflow: hidden; }
  .auditorium-echoes i { position: absolute; left: 0; top: 50%; width: 24px; height: 24px; border: 1px solid #6ad6ea; border-left-color: transparent; border-radius: 50%; transform: translate(-50%,-50%); }
  .auditorium-stage.is-pulsing .auditorium-echoes i { animation: auditorium-echo var(--rt) ease-out both; }
  .auditorium-audience { position: absolute; left: 190px; right: 70px; bottom: 55px; display: grid; grid-template-columns: repeat(9,1fr); gap: 8px 14px; transform: perspective(400px) rotateX(35deg); }
  .auditorium-audience i { width: 10px; height: 10px; border-radius: 50% 50% 3px 3px; border: 1px solid rgba(97,188,205,.23); }
  .auditorium-audience i.occupied { border-color: #66c9dc; background: rgba(102,201,220,.35); box-shadow: 0 0 8px rgba(102,201,220,.22); }
  .auditorium-back-seat { position: absolute; right: 38px; top: 45px; display: flex; align-items: center; gap: 10px; padding: 9px 11px; color: #7ed5e5; border: 1px solid rgba(126,213,229,.24); background: rgba(5,29,40,.75); }
  .auditorium-back-seat span { display: grid; gap: 3px; }
  .auditorium-back-seat small { color: #648f99; font: 700 7px var(--mono); }
  .auditorium-back-seat b { max-width: 190px; color: #afcbd1; font-size: 8px; }
  .auditorium-stage > aside { align-self: stretch; display: grid; align-content: center; justify-items: center; gap: 9px; padding: 25px; text-align: center; background: rgba(5,25,36,.64); }
  .auditorium-stage > aside small { color: #648e99; font: 800 8px var(--mono); letter-spacing: .1em; }
  .auditorium-stage > aside strong { color: #ff9b7d; font: 800 42px var(--mono); }
  .auditorium-stage > aside.ready strong { color: #6ee1bc; }
  .auditorium-stage > aside strong em { margin-left: 4px; color: #7297a1; font-size: 12px; font-style: normal; }
  .auditorium-stage > aside > span { position: relative; width: 100%; height: 8px; border: 1px solid rgba(94,197,216,.22); background: linear-gradient(90deg,#ef7d63 0 20%,#6ee1bc 22% 48%,#e8b85f 52%); }
  .auditorium-stage > aside > span i { position: absolute; top: -4px; width: 2px; height: 14px; background: white; box-shadow: 0 0 8px white; transition: left .4s ease; }
  .auditorium-stage > aside p { color: #7698a0; font-size: 8px; }

  .auditorium-materials > header span,.microphone-challenges > header span { display: grid; gap: 2px; }
  .auditorium-materials > header small,.microphone-challenges > header small { color: #7b9499; font: 800 7px var(--mono); letter-spacing: .1em; }
  .auditorium-materials > header button,.microphone-challenges > header button,.acoustic-reading-strip > header button,.microphone-fallback button { display: flex; align-items: center; gap: 6px; padding: 7px 10px; color: #2d6975; border: 1px solid #a9c4c6; background: rgba(255,255,255,.55); font-size: 9px; font-weight: 800; }
  .auditorium-materials > header button:disabled,.microphone-challenges > header button:disabled { opacity: .45; }
  .auditorium-materials > div { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); }
  .auditorium-materials > div > button { min-height: 128px; display: grid; grid-template-columns: 44px 1fr; grid-template-rows: auto auto 1fr; gap: 4px 10px; padding: 14px; text-align: left; color: #5d7479; border: 0; border-right: 1px solid #d0d9d7; background: transparent; }
  .auditorium-materials > div > button:last-child { border-right: 0; }
  .auditorium-materials > div > button.active { background: #f8faf7; box-shadow: inset 0 3px #4fc2d8; }
  .auditorium-materials button > span { grid-row: 1/4; width: 40px; height: 60px; display: grid; place-items: center; border: 1px solid #aebfbd; background: repeating-linear-gradient(135deg,#d9ddd7 0 3px,#bfc9c6 3px 5px); }
  .auditorium-materials button > span i { width: 100%; height: 100%; background: #48bed3; }
  .auditorium-materials button > b { color: #284c55; font-size: 11px; }
  .auditorium-materials button > small { font: 700 8px var(--mono); }
  .auditorium-materials button > em { align-self: end; font-size: 8px; font-style: normal; line-height: 1.5; }

  .live-mic-stage { min-height: 380px; display: grid; grid-template-columns: 1fr 245px; grid-template-rows: 41px 1fr 48px; }
  .live-mic-stage > header,.live-mic-stage > footer { grid-column: 1/-1; }
  .live-waveform { position: relative; min-height: 285px; padding: 36px 20px 18px; border-right: 1px solid rgba(92,200,222,.18); }
  .live-grid { position: absolute; inset: 18px 20px; border: 1px solid rgba(89,199,219,.19); background: linear-gradient(rgba(93,194,213,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(93,194,213,.08) 1px,transparent 1px); background-size: 24px 24px; }
  .live-waveform svg { position: relative; z-index: 1; width: 100%; height: 210px; filter: drop-shadow(0 0 7px rgba(98,223,241,.4)); }
  .live-waveform polyline { fill: none; stroke: #69dceb; stroke-width: 2; vector-effect: non-scaling-stroke; }
  .live-waveform > span { position: absolute; z-index: 2; left: 31px; top: 28px; display: flex; align-items: center; gap: 7px; color: #78a5af; font: 800 8px var(--mono); }
  .live-mic-stage > aside { display: grid; align-content: center; justify-items: center; gap: 18px; padding: 20px; background: rgba(4,24,34,.55); }
  .live-level-ring { position: relative; width: 135px; height: 135px; display: grid; place-items: center; align-content: center; border: 1px solid rgba(103,211,230,.22); border-radius: 50%; background: radial-gradient(circle,rgba(86,202,222,.08),transparent 68%); }
  .live-level-ring::before { content: ""; position: absolute; inset: 11px; border: 7px solid rgba(93,203,221,.09); border-top-color: #6ee1bc; border-radius: 50%; }
  .live-level-ring > span { position: absolute; left: calc(50% - 1px); bottom: 50%; width: 2px; height: 44px; transform-origin: bottom; background: #ff9b7b; box-shadow: 0 0 8px #ff9b7b; transition: transform .12s linear; }
  .live-level-ring strong { position: relative; z-index: 1; color: #eaf8f9; font: 800 27px var(--mono); }
  .live-level-ring strong em { color: #72a0aa; font-size: 9px; font-style: normal; }
  .live-level-ring small { position: relative; z-index: 1; color: #6d959e; font-size: 8px; }
  .live-frequency { display: grid; justify-items: center; gap: 4px; text-align: center; }
  .live-frequency small { color: #628e98; font: 700 7px var(--mono); }
  .live-frequency strong { color: #6bd9eb; font: 800 24px var(--mono); }
  .live-frequency strong em { margin-left: 3px; color: #6f99a2; font-size: 9px; font-style: normal; }
  .live-frequency span { color: #9bbbc2; font-size: 8px; }
  .live-mic-stage > footer { display: grid; grid-template-columns: repeat(3,1fr); border-top: 1px solid rgba(92,200,222,.18); background: rgba(3,20,29,.72); }
  .live-mic-stage > footer span { display: flex; align-items: center; justify-content: center; gap: 8px; color: #779aa3; border-right: 1px solid rgba(92,200,222,.14); font-size: 8px; }
  .live-mic-stage > footer span:last-child { border-right: 0; }
  .live-mic-stage > footer b { color: #62cadd; font: 800 7px var(--mono); }

  .microphone-fallback { min-height: 68px; display: flex; align-items: center; gap: 12px; padding: 12px 15px; color: #7c5a3e; border: 1px solid #dfc9a9; background: #f3ead9; }
  .microphone-fallback > span { flex: 1; display: grid; gap: 3px; }
  .microphone-fallback b { color: #80513a; font-size: 10px; }
  .microphone-fallback small { font-size: 8px; line-height: 1.5; }
  .microphone-challenges > div { display: grid; grid-template-columns: repeat(3,1fr); }
  .microphone-challenges article { min-height: 92px; padding: 15px; border-right: 1px solid #d0d9d7; }
  .microphone-challenges article:last-child { border-right: 0; }
  .microphone-challenges article b { color: #2c5963; font: 800 10px var(--mono); }
  .microphone-challenges article p { margin: 9px 0 0; color: #718589; font-size: 9px; line-height: 1.65; }

  .acoustic-reading-strip > header { justify-content: flex-start; }
  .acoustic-reading-strip > header button { margin-left: auto; }
  .acoustic-reading-strip > div { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); }
  .acoustic-reading-strip article { min-height: 86px; display: grid; gap: 3px; padding: 12px; border-right: 1px solid #d0d9d7; }
  .acoustic-reading-strip article:last-child { border-right: 0; }
  .acoustic-reading-strip article small { color: #ce6e59; font: 800 8px var(--mono); }
  .acoustic-reading-strip article b { color: #31525a; font-size: 9px; }
  .acoustic-reading-strip article span { color: #75898d; font-size: 8px; }
  .acoustic-reading-strip article strong { align-self: end; color: #278da1; font: 800 14px var(--mono); }

  @keyframes sound-panel-scan { from { translate: -65% 0; } to { translate: 65% 0; } }
  @keyframes acoustic-status { 50% { opacity: .35; box-shadow: 0 0 2px #6ee1bc; } }
  @keyframes campus-wave-travel { 0% { scale: .25; translate: -20px 0; opacity: 0; } 40% { opacity: var(--noise-opacity); } 100% { scale: 4.4; translate: 20px 0; opacity: 0; } }
  @keyframes auditorium-echo { 0% { left: 0; scale: .2; opacity: 0; } 18% { opacity: .85; } 100% { left: 100%; scale: 6; opacity: 0; } }

  @media (max-width: 980px) {
    .campus-scene-selector { grid-template-columns: repeat(2,minmax(0,1fr)); }
    .campus-sound-route { grid-template-columns: 145px 1fr 145px; padding-inline: 18px; }
    .noise-control-console > div { grid-template-columns: 1fr; }
    .noise-control-console > div > section { border-right: 0; border-bottom: 1px solid #d1dad8; }
    .auditorium-materials > div { grid-template-columns: repeat(2,minmax(0,1fr)); }
    .auditorium-materials > div > button:nth-child(2) { border-right: 0; }
    .auditorium-materials > div > button { border-bottom: 1px solid #d0d9d7; }
    .acoustic-reading-strip > div { grid-template-columns: repeat(3,minmax(0,1fr)); }
  }
  @media (max-width: 680px) {
    .campus-scene-selector { grid-template-columns: 1fr; }
    .campus-sound-route { grid-template-columns: 1fr; gap: 9px; padding: 18px; }
    .campus-source,.campus-receiver { min-height: 125px; }
    .campus-wave-path > div { height: 55px; }
    .campus-wave-path > div::after { top: 27px; }
    .campus-level-track { margin-inline: 18px; }
    .auditorium-stage,.live-mic-stage { grid-template-columns: 1fr; }
    .auditorium-stage > header,.live-mic-stage > header,.live-mic-stage > footer { grid-column: 1; }
    .auditorium-room,.live-waveform { border-right: 0; border-bottom: 1px solid rgba(92,200,222,.18); }
    .auditorium-stage > aside { min-height: 190px; }
    .auditorium-materials > div { grid-template-columns: 1fr; }
    .auditorium-materials > div > button { border-right: 0; }
    .live-mic-stage > footer { grid-template-columns: 1fr; }
    .live-mic-stage > footer span { min-height: 34px; border-right: 0; border-bottom: 1px solid rgba(92,200,222,.12); }
    .microphone-challenges > div,.acoustic-reading-strip > div { grid-template-columns: 1fr; }
    .microphone-challenges article,.acoustic-reading-strip article { border-right: 0; border-bottom: 1px solid #d0d9d7; }
    .microphone-fallback { align-items: flex-start; flex-wrap: wrap; }
    .microphone-fallback button { margin-left: 32px; }
  }
  @media (prefers-reduced-motion: reduce) {
    .vision-tech-diagram::before,.future-signal,.future-ray,.future-wave,.retina-scan-line,.future-ai-link,.campus-noise-stage::before,.auditorium-stage::before,.live-mic-stage::before,.campus-wave-path i,.auditorium-echoes i { animation: none; }
  }
}
